.card {
  aspect-ratio: 367.51 / 480.826;
  background: var(--rk-surface);
  border-radius: var(--rk-radius-md);
  cursor: pointer;
  flex: 1 1 0;
  line-height: 1.3;
  min-width: 0;
  overflow: hidden;
  position: relative;
  transition:
    background-color 0.6s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

.isActive {
  background: var(--slide-bg, var(--rk-surface));
  transform: scale(0.96) rotate(2deg);
}

.stage {
  inset: 0;
  opacity: 0;
  pointer-events: none;
  position: absolute;
  transition: opacity 0.4s ease;
  z-index: 0;
}

.stage[data-fruit-loader-ready="true"] {
  opacity: 1;
}

.decor {
  left: 0;
  position: absolute;
  top: 0;
  will-change: transform;
}

.decor svg {
  display: block;
  height: auto;
  width: 100%;
}

.jar {
  inset: 0;
  margin: 0;
  position: absolute;
  transform-origin: 50% 72%;
  transition: transform 1s cubic-bezier(0.22, 1, 0.36, 1);
  z-index: 1;
}

.isActive .jar {
  transform: scale(1.1) rotate(4deg);
}

.jar img {
  display: block;
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.link {
  inset: 0;
  position: absolute;
  z-index: 2;
}

.link:focus-visible {
  border-radius: var(--rk-radius-md);
  box-shadow: 0 0 0 5px var(--rk-bg);
  outline: 2px solid var(--rk-fg);
  outline-offset: -4px;
}

@media (prefers-reduced-motion: reduce) {
  .card,
  .jar {
    transition: none;
  }
}

.previewRail {
  display: flex;
  gap: 15px;
  left: 50%;
  padding-inline: clamp(30px, 2vw, 40px);
  position: relative;
  transform: translateX(-50%);
  width: 100vw;
}

.previewRail > * {
  flex: 1 1 0;
  min-width: 0;
}

@media (max-width: 1024px) {
  .previewRail {
    overflow-x: auto;
    scrollbar-width: none;
  }

  .previewRail::-webkit-scrollbar {
    display: none;
  }

  .previewRail > * {
    flex: 0 0 calc(40vw - clamp(30px, 2vw, 40px) * 2 / 2.5 - 15px);
  }
}

