.isArrow:hover .iconBefore {
  transform: none;
}

.isArrow:hover .iconAfter {
  transform: translateX(100%);
}

.left .iconBefore {
  transform: rotate(180deg);
}

.left .iconAfter {
  transform: translateX(100%) rotate(180deg);
