  width: 4.875em; height: 5em; margin-right: -1.8em;
  transform-origin: bottom right; translate: 0 2px 0;
  transform: rotate(-36deg) scale(0); transition: transform 0.25s var(--_ease-smooth);
}

.rightEar {
  width: 3.25em; height: 9em;
  transform-origin: bottom center; translate: 0 2px 0;
  transform: rotate(-80deg) scale(0); transition: transform 0.25s var(--_ease-smooth);
}

.itemBgBottom {
  background-color: var(--rk-bc-soft-pink, var(--rk-surface));
  border-bottom-right-radius: 2em;
  border-bottom-left-radius: 2em;
  width: 100%;
  height: 5em;
  transition: translate 0.4s var(--_ease-smooth);
}

.itemCta {
  justify-content: center;
  align-items: center;
  display: flex;
  position: absolute;
  bottom: -3em;
  pointer-events: none;
}

.ctaPill {
  display: inline-flex; height: 3.5em; font-family: var(--rk-font-body);
  font-weight: 700; letter-spacing: -0.03em; color: var(--rk-bc-white, var(--rk-bg));
}

.ctaTextWrap, .ctaIconWrap {
  display: grid; opacity: 0; translate: 0 -1.5em 0;
  transition: opacity 0.1s var(--_ease-smooth), translate 0.35s var(--_ease-bounce), rotate 0.35s var(--_ease-bounce), transform 0.35s var(--_ease-bounce);
}

.ctaIconWrap { aspect-ratio: 1; width: 3.5em; height: 3.5em; margin-left: -0.0625em; }

.ctaBg {
  background-color: var(--rk-bc-magenta, var(--rk-accent));
  border-radius: var(--rk-radius-sm, 0.5em);
  grid-area: 1 / 1; width: 100%; height: 100%;
}

.ctaTextOuter, .ctaIconOuter {
  z-index: 1; grid-area: 1 / 1; display: flex; justify-content: center; align-items: center; padding: 0 1em;
}

.ctaIconOuter { padding: 0; }
.ctaText { font-size: 1.25em; }
.ctaArrow { width: 0.875em; height: 0.75em; }

.itemContainer {
  gap: 1em; z-index: 1; flex-flow: column; grid-area: 1 / 1;
  width: 100%; height: 100%; padding: 1em 1em 1.5em; display: flex;
}

.itemCover { aspect-ratio: 320 / 493; border-radius: 1em; width: 100%; overflow: clip; background-color: var(--rk-bc-soft-grey, var(--rk-surface)); }
.itemImg { object-fit: cover; width: 100%; height: 100%; display: block; -webkit-user-drag: none; }
.itemContent { gap: 0.75em; flex-flow: column-reverse; display: flex; }
.itemText { gap: 0.5em; hyphens: auto; flex-flow: column; padding: 0 0.125em; display: flex; }

.itemTitle {
  font-family: var(--rk-font-display);
  font-size: var(--rk-bc-heading-s, 2.5em);
  line-height: 0.88;
  margin: 0;
}

.itemDesc {
  font-family: var(--rk-font-body);
  font-size: var(--rk-bc-para-small, 1.25em);
  letter-spacing: -0.02em;
  line-height: 1.2;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow: hidden;
  margin: 0;
}

.genreList {
  gap: 0.25em; flex-flow: wrap; justify-content: flex-start;
  align-items: flex-start; margin: 0; padding: 0; list-style: none; display: flex;
}

.tagSmall { border-radius: 1.5em; justify-content: center; align-items: center; padding: 0.4375em 0.5em; display: inline-flex; }
.tagSmallText { font-family: var(--rk-font-body); font-size: 1.125em; line-height: 1; font-weight: 600; }

.itemLink { z-index: 2; grid-area: 1 / 1; width: 100%; height: 100%; position: relative; -webkit-user-drag: none; }

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .item:has(.itemLink:hover) .itemBgBottom { translate: 0 1.5em 0; transition: translate 0.35s 0.1s var(--_ease-bounce); }
  .item:has(.itemLink:hover) .ctaTextWrap { opacity: 1; translate: 0 0 0; rotate: -16deg; transform: rotate(16deg); transition-delay: 0.15s; }
  .item:has(.itemLink:hover) .ctaIconWrap { opacity: 1; translate: 0 0 0; rotate: 16deg; transform: rotate(-16deg); transition-delay: 0.15s; }
  .item:has(.itemLink:hover) .leftEar { transform: rotate(0deg) scale(1); transition: transform 0.45s 0.15s var(--_ease-bounce); }
  .item:has(.itemLink:hover) .rightEar { transform: rotate(0deg) scale(1); transition: transform 0.45s 0.1s var(--_ease-bounce); }
  .item:has(.itemLink:hover) .itemInner { rotate: calc(var(--book-slider-item-rotate, -2deg) * 1.3); transition: rotate 0.35s 0.1s var(--_ease-bounce); }
