  .itemContainer { gap: 0.75em; padding: 0.75em 0.75em 1.125em; }
  .itemCover { border-radius: 0.75em; }
  .itemContent { gap: 0.5625em; }
  .genreList { gap: 0.1875em; }
  .itemText { gap: 0.375em; }
