}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .item:has(.itemLink:hover) .itemInner { rotate: calc(var(--book-slider-item-rotate, -2deg) * 1.3); }
}

@media screen and (max-width: 991px) {
  .choice { margin-top: -5em; clip-path: inset(var(--_margin) round 2em); }
  .header { padding-top: 4.5em; padding-bottom: 1.5em; }
  .headerContent { gap: 0.75em; }
  .easterEgg, .itemBgEars { display: none; }
  .visual { top: 2.875em; left: 2.25em; }
  .visualImg { width: 4.1875em; height: 3.75em; }
  .content { padding-bottom: 5.5em; }
  .list { scroll-snap-type: x mandatory; padding: 3em 2.5em; overflow-x: scroll; }
  .listItem { scroll-snap-align: start; width: 20em; }
  .listItem:first-child .item { padding-left: 3em; }
  .listItem:last-child .item { padding-right: 3em; }
  .listItem:nth-child(even) .itemInner { rotate: 1.2deg; translate: 0 1em; }
  .listItem:nth-child(odd) .itemInner { rotate: -0.6deg; translate: 0 -1em; }
  .item { padding-left: 1.875em; padding-right: 1.875em; }
