.listItem:has(+ .listItem:hover .link) .link { translate: 0 -2em; }
.listItem:has(+ .listItem + .listItem:hover .link) .link { translate: 0 -0.75em; }

.listItem:hover .linkDefault { filter: blur(0.0625em); opacity: 0; scale: 0.75 1.25; transition: opacity 0.15s 0.05s var(--_ease-smooth), scale 0.3s var(--_ease-bounce), filter 0.25s var(--_ease-smooth); }
.listItem:hover .linkHover { opacity: 1; scale: 1 1; filter: blur(0); transition: opacity 0.15s 0.05s var(--_ease-smooth), scale 0.3s var(--_ease-bounce), filter 0.25s var(--_ease-smooth); }

.holding { pointer-events: none; width: 100%; height: 8em; left: 50%; top: calc(var(--start-index, 0) * 8em); position: absolute; translate: -50%; }
.scope { width: 100%; height: 100%; translate: 0% calc(var(--active-index, 0) * 8em); position: relative; transition: width 0.2s, translate var(--translate-speed, 0.2s); }
.holder { aspect-ratio: 272 / 419; width: 17em; position: absolute; top: 50%; left: 50%; }

.holder:nth-of-type(1) { --offset-x: calc(-150% - (var(--start-width, 200) * 0.5px)); translate: var(--offset-x) -100%; }
.holder:nth-of-type(2) { --offset-x: calc(50% + (var(--start-width, 200) * 0.5px)); translate: var(--offset-x) -100%; }
.holder:nth-of-type(3) { --offset-x: calc(-150% - (var(--start-width, 200) * 0.5px)); translate: var(--offset-x) 50%; }
.holder:nth-of-type(4) { --offset-x: calc(50% + (var(--start-width, 200) * 0.5px)); translate: var(--offset-x) 50%; }

.box {
  isolation: isolate; display: grid; scale: 0;
  transform: translate(calc(var(--x, 0) * 1%), calc(var(--y, 0) * 1%)) rotate(calc(var(--r, 0) * 1deg)) translate(calc(var(--px, 0) * var(--prx, 0%)), calc(var(--py, 0) * var(--pry, 0%)));
  transition: translate 0.85s var(--_ease-elastic), scale 0.4s var(--_ease-bounce), transform 0.85s var(--_ease-elastic);
}

.holder:nth-of-type(1) .box { --prx: 15%; --pry: 10%; translate: calc(var(--active-offset, 0) * -0.5px) 0%; }
.holder:nth-of-type(2) .box { --prx: -15%; --pry: -10%; translate: calc(var(--active-offset, 0) * 0.5px) 0%; }
