.img { object-fit: cover; border-radius: 0.875em; grid-area: 1 / 1; width: 100%; height: 100%; opacity: 0; transition: opacity 0.2s 0s; box-shadow: 0 0 0 0.25em var(--rk-bc-white, var(--rk-bg)); }

.list:has(li:is(:hover, :focus-within)) + .holding .box { scale: 1; }
.listWrap:has(li:nth-of-type(1):hover) .box > *:nth-child(1),
.listWrap:has(li:nth-of-type(2):hover) .box > *:nth-child(2),
