.easterEgg { justify-content: center; align-items: center; padding-top: 1.5em; display: flex; }

@media screen and (max-width: 991px) {
  .genre { clip-path: inset(0 round 2.5em); }
  .inner { padding-bottom: 4em; }
  .header { padding-top: 4em; }
  .title, .textWrap { display: none; }
