.in .line {
  animation: 0.72s cubic-bezier(0.22, 1, 0.36, 1) forwards s2rise;
}

.in .head .line:nth-child(1) {
  animation-delay: 80ms;
}

.in .head .line:nth-child(2) {
  animation-delay: 0.26s;
}

.in .head .line:nth-child(3) {
  animation-delay: 0.44s;
}

.in .head .line:nth-child(4) {
  animation-delay: 0.62s;
}

.in .head .line:nth-child(n + 5) {
