      color-mix(in srgb, var(--rk-bg) 0%, transparent) 100%
    );
  }

  .toneLight::after {
    background: linear-gradient(
      color-mix(in srgb, var(--rk-fg) 0%, transparent) 0%,
      color-mix(in srgb, var(--rk-fg) 75%, transparent) 22%,
      var(--rk-fg) 32% 64%,
      color-mix(in srgb, var(--rk-fg) 75%, transparent) 76%,
      color-mix(in srgb, var(--rk-fg) 0%, transparent) 100%
    );
  }

  .head {
    font-size: clamp(40px, 13vw, 54px);
  }

  .head .line {
    white-space: normal;
    margin-left: 0 !important;
  }

  .body {
    display: grid;
    grid-template-columns: 88px 1fr;
    gap: 20px;
    width: auto;
    max-width: none;
    margin-top: 40px;
    margin-left: 0;
    font-size: 16px;
  }

  .body::before {
    content: attr(data-label);
    color: var(--rk-fg);
    font-size: 14px;
    line-height: 1.31;
  }

  .toneLight .body::before {
    color: var(--rk-bg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .line,
  .body {
    opacity: 1;
    transform: none;
    animation: none;
  }
}

