  font-size: 38px;
  font-weight: 300;
  line-height: 1;
  text-transform: uppercase;
}
.prompt { margin-bottom: 32px; }

.options {
  display: grid;
  grid-template-columns: 1fr;
  gap: 14px;
  margin-bottom: 36px;
}

.option {
  background: var(--rk-surface-elevated);
  color: var(--rk-fg);
