  text-transform: uppercase;
  transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}
.option:hover,
.optionSelected {
  background: var(--rk-fg);
  color: var(--rk-bg);
  border-color: var(--rk-fg);
}

.nav {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  align-items: center;
}

.btn {
  position: relative;
  display: inline-block;
  padding: 5px;
  border-radius: 3px;
  font-family: var(--rk-font-display);
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 0.6s var(--rk-ease, cubic-bezier(0.215, 0.61, 0.355, 1)),
    color 0.6s var(--rk-ease, cubic-bezier(0.215, 0.61, 0.355, 1)),
    border-color 0.6s var(--rk-ease, cubic-bezier(0.215, 0.61, 0.355, 1));
}
.btnDark {
