.btnGhost {
  background-color: transparent;
  color: var(--rk-fg);
  border: 1.25px solid var(--rk-fg);
}
.btn:not(:disabled):hover,
.btn:not(:disabled):active {
  background-color: var(--rk-surface-elevated);
  color: var(--rk-fg);
  border-color: transparent;
}
.nav button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.result {
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px;
  align-items: center;
}
.resultDesc {
  margin: 20px 0 28px;
  max-width: 58ch;
  font-family: var(--rk-font-body);
  font-size: 16px;
  line-height: 1.35;
}
.resultActions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  align-items: center;
}
.retake {
  background: transparent;
  border: 0;
  padding: 0;
  cursor: pointer;
  color: var(--rk-fg);
  text-decoration: underline;
  margin-left: 8px;
  font-family: var(--rk-font-body);
  font-size: 14px;
