.resultMedia { display: flex; justify-content: center; }
.resultMedia img { max-width: 280px; width: 100%; height: auto; object-fit: contain; }
.resultPlaceholder {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 220px;
  height: 260px;
  background: var(--rk-surface);
  color: color-mix(in srgb, var(--rk-fg) 35%, transparent);
  border: 1px solid color-mix(in srgb, var(--rk-fg) 12%, transparent);
}

.option:focus-visible,
.btn:focus-visible,
.retake:focus-visible {
  outline: 2px solid var(--rk-accent);
  outline-offset: 2px;
}

@media only screen and (min-width: 768px) {
  .options { grid-template-columns: repeat(2, 1fr); }
}

@media only screen and (min-width: 1024px) {
  .section { --outside-gutter: 52px; }
  .eyebrow { font-size: min(18px, min(1.25vw, 2.2222222222vh)); }
  .prompt,
  .resultTitle { font-size: min(5.2083333333vw, 9.2592592593vh); }
  .option { font-size: min(3.4722222222vw, 6.1728395062vh); }
  .btn {
    padding: min(0.3472222222vw, 0.6172839506vh);
    font-size: min(1.8055555556vw, 3.2098765432vh);
  }
  .result { grid-template-columns: 1.3fr 0.7fr; }
  .resultDesc { font-size: min(18px, min(1.25vw, 2.2222222222vh)); }
  .retake { font-size: min(16px, min(1.1111111111vw, 1.975308642vh)); }
}

@media (prefers-reduced-motion: reduce) {
  .progressBar,
  .option,
  .btn,
  .retake { transition: none; }
}

