.spoke { position: absolute; inset: 0; }
.crest {
  position: absolute;
  top: 0;
  left: 50%;
  width: 12.15vw;
  height: 12.1vw;
  transform: translate(-50%, -50%);
}
.crestArt {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  transform: scale(calc(0.5 + 0.5 * (1 - var(--rk-wheel-off, 0))));
  transform-origin: 50%;
}
.shader {
  position: absolute;
  top: 51.9vw;
  left: 0;
  right: 0;
  z-index: 2;
  height: 14.4vw;
  pointer-events: none;
}
.shaderBlur {
  position: absolute;
  inset: 0;
  --blurk: max(0, 1 - var(--rk-wheel-off, 0) * 4);
}
.sb1 {
  backdrop-filter: blur(calc(5px * var(--blurk, 1)));
  -webkit-backdrop-filter: blur(calc(5px * var(--blurk, 1)));
  -webkit-mask-image: linear-gradient(transparent 0%, var(--rk-bg) 42% 100%);
  mask-image: linear-gradient(transparent 0%, var(--rk-bg) 42% 100%);
}
.sb2 {
  backdrop-filter: blur(calc(15px * var(--blurk, 1)));
  -webkit-backdrop-filter: blur(calc(15px * var(--blurk, 1)));
  -webkit-mask-image: linear-gradient(transparent 28%, var(--rk-bg) 72%);
  mask-image: linear-gradient(transparent 28%, var(--rk-bg) 72%);
}
.shaderGrad {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    color-mix(in srgb, var(--rk-fg) 0%, transparent) 0%,
    color-mix(in srgb, var(--rk-fg) 98%, var(--rk-bg)) 79%
  );
}
.cover {
  position: absolute;
  inset: 66vw 0 0;
  z-index: 2;
  background: color-mix(in srgb, var(--rk-fg) 98%, var(--rk-bg));
}

.kicker {
  position: absolute;
  top: 40.2vw;
  left: 50%;
  z-index: 3;
  margin: 0;
  opacity: 0;
  white-space: nowrap;
  font-size: 14px;
  font-weight: 500;
  line-height: normal;
  transform: translate(-50%);
  translate: 0 calc((var(--rk-wheel-par, 0.5) - 0.5) * -3vw);
}

.in .kicker {
  animation: 0.6s cubic-bezier(0.22, 1, 0.36, 1) 50ms forwards orbitalFade;
}

.headWrap {
  position: absolute;
  top: 42.6vw;
  left: 50%;
  z-index: 3;
  width: 60vw;
  transform: translate(-50%);
  translate: 0 calc((var(--rk-wheel-par, 0.5) - 0.5) * -3vw);
}

.head,
.lead {
  margin: 0;
  text-transform: uppercase;
  letter-spacing: -0.01em;
  font-family: var(--rk-font-display);
  font-size: 6.4vw;
  font-weight: 300;
  line-height: 0.88;
}

.head {
  text-align: center;
}

.headRow {
