}

.letter {
  display: inline-block;
  --w: clamp(0, calc((var(--rk-wheel-hl, 1) * 40 - var(--i, 0)) / 5), 1);
  --out: clamp(0, calc((var(--rk-wheel-morph, 0) * 90 - var(--i, 0)) / 6), 1);
  opacity: calc(var(--w) * (1 - var(--out)));
  transform: translateY(calc((1 - var(--w)) * 0.38em + var(--out) * 0.42em));
  will-change: opacity, transform;
}

@keyframes orbitalFade {
  to {
    opacity: 1;
    transform: translate(-50%) translateY(0);
  }
}

.leadStack {
