  --w: clamp(0, calc((var(--rk-wheel-morph, 0) * 100 - 50 - var(--i, 0)) / 7), 1);
  opacity: var(--w);
  transform: translateY(calc((1 - var(--w)) * 1em));
  will-change: opacity, transform;
}

.blurbBody {
