function renderBattlementMotif() {
  const rows = [0, 1, 2, 3];
  const cols = [0, 1, 2];
  return (
    <g>
      <rect width="74" height="74" fill={ACCENT} />
      {rows.map((row) =>
        cols.map((col) => {
          const offsetX = row % 2 === 1 ? 12.3 : 0;
          const x = col * 24.6 + offsetX - 4;
          const y = row * 18.5;
          return (
            <path
              key={`${row}-${col}`}
              d={`M${x} ${y}h14v6h-4v12.5h-6V${y + 6}h-4Z`}
              fill={INK}
            />
          );
        }),
      )}
    </g>
