  position: absolute;
  text-align: center;
  text-transform: uppercase;
  transform: translate3d(0, 28px, 0);
  transition:
    opacity 0.9s var(--rk-ease) 0.18s,
    transform 0.9s var(--rk-ease) 0.18s;
  width: 100%;
}

.promptReady {
  opacity: 1;
  transform: translateZ(0);
}

.wrapper {
  cursor: grab;
  inset: 0;
  overflow: hidden;
  position: absolute;
  touch-action: none;
  z-index: 2;
}

.wrapper:active {
  cursor: grabbing;
}

.marquee {
  height: var(--jar-marquee-h);
  left: 50%;
  position: absolute;
  top: var(--jar-marquee-top);
  transform: translate(-50%, -50%) rotate(var(--jar-marquee-angle));
  width: var(--jar-marquee-w);
}

.track {
  height: 100%;
  position: relative;
  width: 100%;
}

.item {
  color: inherit;
  cursor: pointer;
  height: var(--jar-item-h);
  left: 0;
  margin-top: calc(var(--jar-item-h) / -2);
  pointer-events: auto;
  position: absolute;
  text-decoration: none;
  top: 50%;
  width: var(--jar-item-w);
  will-change: transform, opacity, filter;
}

.item canvas,
.item img {
  height: 100%;
  inset: 0;
  pointer-events: none;
  position: absolute;
  user-select: none;
  width: 100%;
}

@media (max-width: 1024px) {
  .hero {
    --jar-marquee-top: 43%;
  }
}

@media (max-width: 480px) {
  .hero {
    --jar-marquee-top: 45%;
    --jar-item-w: 24.33vw;
    --jar-item-h: 39.13vw;
  }

  .shapeLayer {
    width: 120vw;
  }

  .badge {
    width: 72%;
  }

  .cta {
    min-height: 84px;
    min-width: 84px;
  }

  .prompt {
    max-width: calc(100vw - 32px);
  }
}

