export interface InputState {
  target: number;
  dragging: boolean;
  pointerInside: boolean;
  pointerX: number;
  pointerY: number;
}

export function attachMarqueeInput(
  root: HTMLElement,
  wrap: HTMLElement,
  onResize: () => void,
) {
  const state: InputState = {
    target: 0,
    dragging: false,
    pointerInside: false,
    pointerX: 0,
    pointerY: 0,
  };

  let pressed = false;
  let pointerId = -1;
  let wasDragged = false;
  let lastX = 0;
  let downX = 0;
  let dragVelocity = 0;
  let lastDragTime = 0;

  const onWheel = (e: WheelEvent) => {
    e.preventDefault();
    const d = Math.abs(e.deltaY) >= Math.abs(e.deltaX) ? e.deltaY : e.deltaX;
    state.target -= d * 1.15;
  };
  const onPointerDown = (e: PointerEvent) => {
    pressed = true;
    pointerId = e.pointerId;
    state.dragging = false;
    wasDragged = false;
    lastX = e.clientX;
    downX = e.clientX;
    dragVelocity = 0;
    lastDragTime = e.timeStamp || performance.now();
  };
  const onPointerMove = (e: PointerEvent) => {
    if (!pressed || e.pointerId !== pointerId) return;
    if (!state.dragging) {
      if (Math.abs(e.clientX - downX) <= 6) return;
      wrap.setPointerCapture?.(e.pointerId);
      state.dragging = true;
      wasDragged = true;
      lastX = e.clientX;
      lastDragTime = e.timeStamp || performance.now();
      return;
    }
    const dx = e.clientX - lastX;
    const now = e.timeStamp || performance.now();
    const dtMs = Math.max(1, now - lastDragTime);
    dragVelocity = dragVelocity * 0.72 + (dx / dtMs) * 0.28;
    lastX = e.clientX;
    lastDragTime = now;
    state.target += dx * 1.5;
  };
  const onPointerUp = (e: PointerEvent) => {
    if (pointerId !== -1 && e.pointerId !== pointerId) return;
    if (state.dragging) {
      wrap.releasePointerCapture?.(e.pointerId);
      const v = Math.max(-3.5, Math.min(3.5, dragVelocity));
      state.target += v * 1.5 * 190;
    }
    dragVelocity = 0;
    pressed = false;
    pointerId = -1;
    state.dragging = false;
  };
  const onRootMove = (e: PointerEvent) => {
    if (e.pointerType !== "touch") {
      state.pointerInside = true;
      state.pointerX = e.clientX;
      state.pointerY = e.clientY;
    }
  };
  const onRootLeave = () => {
    state.pointerInside = false;
  };
  const onClickCapture = (e: MouseEvent) => {
    if (wasDragged) {
      e.preventDefault();
      e.stopPropagation();
    }
  };

  window.addEventListener("resize", onResize);
  wrap.addEventListener("wheel", onWheel, { passive: false });
  wrap.addEventListener("pointerdown", onPointerDown);
  wrap.addEventListener("pointermove", onPointerMove);
  wrap.addEventListener("pointerup", onPointerUp);
  wrap.addEventListener("pointercancel", onPointerUp);
  wrap.addEventListener("click", onClickCapture, true);
  root.addEventListener("pointermove", onRootMove, { passive: true });
  root.addEventListener("pointerleave", onRootLeave);

  return {
    state,
    destroy: () => {
      window.removeEventListener("resize", onResize);
      wrap.removeEventListener("wheel", onWheel);
      wrap.removeEventListener("pointerdown", onPointerDown);
      wrap.removeEventListener("pointermove", onPointerMove);
      wrap.removeEventListener("pointerup", onPointerUp);
      wrap.removeEventListener("pointercancel", onPointerUp);
      wrap.removeEventListener("click", onClickCapture, true);
      root.removeEventListener("pointermove", onRootMove);
      root.removeEventListener("pointerleave", onRootLeave);
    },
  };
}

extraFiles.jar-math.ts:
import type { JarMaterial } from "./jar-renderer";

export const ROT_AMPLITUDE = 18;
export const Y_OFFSETS = [-0.053, 0.043, -0.024, 0.057, -0.048, 0.029, -0.038, 0.053];
export const SPIN_DURATION = 2;
export const HOVER_DWELL_MS = 260;
export const MOTION_THRESHOLD = 6;
export const SCALE_MIN = 0.55;
export const SCALE_MAX = 1.35;
export const EDGE_SHRINK = 0.1;
export const BRIGHT_MIN = 0.7;
export const BRIGHT_MAX = 1.1;
export const INTRO_MS = 1150;
export const INTRO_RISE = 56;
export const INTRO_SCALE = 0.9;
export const BADGE_INTRO_ROTATION = -18;
export const SPRING_STIFFNESS = 70;
export const SPRING_DAMPING = 9;

export interface Spring {
  value: number;
  velocity: number;
}

export interface LabelRec {
  element: HTMLElement;
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  labelUrl: string;
  jar: JarMaterial | null;
  labelReady: boolean;
  cycleStart: number;
  hoverQueued: boolean;
  isPointerOver: boolean;
  pointerEnterTime: number;
  hoverDwellStart: number;
  renderedOffset: number;
  needsRender: boolean;
  turn: Spring;
  lean: Spring;
  lift: Spring;
  pullX: Spring;
  pullY: Spring;
  teardown: () => void;
}

export const spring = (): Spring => ({ value: 0, velocity: 0 });

export const stepSpring = (s: Spring, target: number, stiffness: number, dt: number) => {
  s.velocity += ((target - s.value) * stiffness - s.velocity * SPRING_DAMPING) * dt;
  s.value += s.velocity * dt;
  if (Math.abs(s.velocity) < 0.001 && Math.abs(target - s.value) < 0.001) {
    s.value = target;
    s.velocity = 0;
  }
};

export const easeOutCubic = (t: number) => 1 - (1 - t) ** 3;
export const easeInOutQuint = (t: number) =>
  t < 0.5 ? 16 * t * t * t * t * t : 1 - (-2 * t + 2) ** 5 / 2;

export function createLabelRecords(items: HTMLElement[], canHover: () => boolean): LabelRec[] {
  return items
    .map((element): LabelRec | null => {
      const canvas = element.querySelector("canvas");
      const labelUrl = element.dataset.label || "";
      const ctx = canvas?.getContext("2d") ?? null;
      if (!canvas || !ctx || !labelUrl) return null;
      const rec: LabelRec = {
        element,
        canvas,
        ctx,
        labelUrl,
        jar: null,
        labelReady: false,
        cycleStart: -1,
        hoverQueued: false,
        isPointerOver: false,
        pointerEnterTime: -1,
        hoverDwellStart: -1,
        renderedOffset: Number.NaN,
        needsRender: true,
        turn: spring(),
        lean: spring(),
        lift: spring(),
        pullX: spring(),
        pullY: spring(),
        teardown: () => {},
      };
      const onEnter = () => {
        if (!canHover()) return;
        rec.isPointerOver = true;
        rec.hoverQueued = true;
        rec.pointerEnterTime = performance.now();
      };
      const onLeave = () => {
        rec.isPointerOver = false;
        rec.hoverQueued = false;
      };
      element.addEventListener("pointerenter", onEnter);
      element.addEventListener("pointerleave", onLeave);
      rec.teardown = () => {
        element.removeEventListener("pointerenter", onEnter);
        element.removeEventListener("pointerleave", onLeave);
      };
      return rec;
    })
    .filter((l): l is LabelRec => !!l);
}

extraFiles.jar-renderer.ts:
import type * as ThreeNS from "three";

type Three = typeof ThreeNS;

export interface JarMaterial {
  setOffset: (v: number) => void;
  dispose: () => void;
}

export interface JarRenderer {
  createMaterial: (url: string, onLoad: () => void, onError: () => void) => JarMaterial;
  render: (jar: JarMaterial, offset: number) => void;
  blit: (ctx: CanvasRenderingContext2D) => void;
  resize: (canvases: HTMLCanvasElement[]) => void;
  dispose: () => void;
}

export const JAR_RATIO = 630 / 1013;
export const SCALE_MAX = 1.35;
export const FRONT_ROT = 182;

const CYL_TOP = 0.27;
const CYL_BOT = 0.87;
const CYL_WIDTH = 0.885;
const CYL_CURV = 3;
const GAP_LABEL = 0.09;
const LIGHT_INT = 0.58;
const LIGHT_AMB = 0.89;
const LIGHT_X = -1;

const pixelRatioFor = (w: number, h: number, scale = 1, count = 1) => {
  const dpr = Math.min(window.devicePixelRatio || 1, 3);
  const px = w * scale * h * scale * count;
  return px ? Math.max(1, Math.min(dpr, Math.sqrt(12e6 / px))) : dpr;
};

export function createJarWebGLRenderer(THREE: Three, onResizeDone: () => void): JarRenderer {
  const gl = new THREE.WebGLRenderer({ alpha: true, antialias: true });
  gl.outputColorSpace = THREE.SRGBColorSpace;
  const anisotropy = gl.capabilities.getMaxAnisotropy();
  const loader = new THREE.TextureLoader();

  const scene = new THREE.Scene();
  const camera = new THREE.OrthographicCamera(-JAR_RATIO / 2, JAR_RATIO / 2, 0.5, -0.5, 0.01, 10);
  camera.position.z = 5;
  scene.add(new THREE.AmbientLight(0xffffff, LIGHT_AMB));
  const spot = new THREE.SpotLight(0xffffff, LIGHT_INT * 5);
  spot.distance = 6;
  spot.angle = Math.PI / 4;
  spot.penumbra = 0.7;
  spot.decay = 1.2;
  spot.position.set(LIGHT_X, 0.5, 0.6);
  scene.add(spot, spot.target);
  spot.target.position.x = 0;
  spot.target.updateMatrixWorld();

  const mesh = new THREE.Mesh();
  scene.add(mesh);
  const cylHeight = CYL_BOT - CYL_TOP;
  const radius = (CYL_WIDTH * JAR_RATIO) / 2;
  const profile: ThreeNS.Vector2[] = [];
  for (let i = 0; i <= 16; i += 1) {
    profile.push(new THREE.Vector2(radius, (i / 16 - 0.5) * cylHeight));
  }
  mesh.geometry = new THREE.LatheGeometry(profile, 128);
  mesh.position.y = 0.5 - (CYL_TOP + CYL_BOT) / 2;
  mesh.rotation.x = (CYL_CURV * Math.PI) / 180;

  let bufW = 0;
  let bufH = 0;
  const matMap = new WeakMap<JarMaterial, ThreeNS.MeshStandardMaterial>();

  return {
    createMaterial: (url, onLoad, onError) => {
      const uGap = { value: GAP_LABEL };
      const uOffset = { value: FRONT_ROT / 360 };
      const map = loader.load(url, onLoad, undefined, onError);
      map.wrapS = THREE.RepeatWrapping;
      map.wrapT = THREE.ClampToEdgeWrapping;
      map.colorSpace = THREE.SRGBColorSpace;
      map.generateMipmaps = true;
      map.minFilter = THREE.LinearMipmapLinearFilter;
      map.magFilter = THREE.LinearFilter;
      map.anisotropy = anisotropy;

      const material = new THREE.MeshStandardMaterial({
        map,
        side: THREE.FrontSide,
        roughness: 0.72,
        metalness: 0,
      });
      material.onBeforeCompile = (shader) => {
        shader.uniforms.uGap = uGap;
        shader.uniforms.uOffset = uOffset;
        shader.fragmentShader = shader.fragmentShader.replace(
          "#include <common>",
          "#include <common>\nuniform float uGap;\nuniform float uOffset;",
        );
        shader.fragmentShader = shader.fragmentShader.replace(
          "#include <map_fragment>",
          `#ifdef USE_MAP
            float _u = fract(vMapUv.x + uOffset);
            if (_u >= 1.0 - uGap) discard;
            float _r = _u / max(1.0 - uGap, 0.001);
            vec4 sampledDiffuseColor = texture2D(map, vec2(_r, vMapUv.y));
            diffuseColor *= sampledDiffuseColor;
          #endif`,
        );
      };

      const record: JarMaterial = {
        setOffset: (v) => {
          uOffset.value = v;
        },
        dispose: () => {
          material.dispose();
          map.dispose();
        },
      };
      matMap.set(record, material);
      return record;
    },
    render: (jar, offset) => {
      const mat = matMap.get(jar);
      if (!mat) return;
      jar.setOffset(offset);
      mesh.material = mat;
      gl.render(scene, camera);
    },
    blit: (ctx) => {
      ctx.clearRect(0, 0, bufW, bufH);
      ctx.drawImage(gl.domElement, 0, 0);
    },
    resize: (canvases) => {
      const first = canvases[0];
      const w = first?.offsetWidth ?? 0;
      const h = first?.offsetHeight ?? 0;
      if (!w || !h) return;
      gl.setPixelRatio(pixelRatioFor(w, h, SCALE_MAX, canvases.length));
      gl.setSize(w * SCALE_MAX, h * SCALE_MAX, false);
      bufW = gl.domElement.width;
      bufH = gl.domElement.height;
      for (const c of canvases) {
        c.width = bufW;
        c.height = bufH;
      }
      onResizeDone();
    },
    dispose: () => {
      mesh.geometry?.dispose();
      gl.dispose();
      gl.forceContextLoss?.();
    },
  };
}

extraFiles.jar-slider.ts:
import { attachMarqueeInput } from "./jar-input";
import {
  BADGE_INTRO_ROTATION,
  BRIGHT_MAX,
  BRIGHT_MIN,
  createLabelRecords,
  easeInOutQuint,
  easeOutCubic,
  EDGE_SHRINK,
  HOVER_DWELL_MS,
  INTRO_MS,
  INTRO_RISE,
  INTRO_SCALE,
  MOTION_THRESHOLD,
  ROT_AMPLITUDE,
  SCALE_MAX,
  SCALE_MIN,
  SPIN_DURATION,
  SPRING_STIFFNESS,
  stepSpring,
  Y_OFFSETS,
} from "./jar-math";
import { createJarWebGLRenderer, FRONT_ROT, JAR_RATIO, type JarRenderer } from "./jar-renderer";

const JAR_ASPECT = 1 / JAR_RATIO;
const ITEM_SIZE_MULT = 1.15;

export function createJarMarquee(
  root: HTMLElement,
  opts: { labelDelayMs?: number } = {},
): { destroy: () => void } | null {
  const wrap = root.querySelector<HTMLElement>("[data-jar-slider-wrap]");
  const track = root.querySelector<HTMLElement>("[data-jar-slider-track]");
  const items = Array.from(root.querySelectorAll<HTMLElement>("[data-jar-slider-item]"));
  if (!wrap || !track || !items.length) return null;

  const count = items.length;
  let itemW = 0, itemH = 0, slotW = 0, totalLen = 0, waveLen = 0, wrapPad = 0;
  let trackCx = 0, trackCy = 0, cosA = 1, sinA = 0;
  const hoverMq = window.matchMedia("(hover: hover) and (pointer: fine)");
  const reducedMq = window.matchMedia("(prefers-reduced-motion: reduce)");

  const layout = () => {
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const phone = vw <= 480;
    const tablet = !phone && vw <= 1024;
    const slotBase = vw / (phone || tablet ? 3 : 4);
    slotW = slotBase * (phone ? 1.15 : tablet ? 1.265 : 0.92);
    itemW = slotBase * (phone ? 0.73 : tablet ? 0.7875 : 0.5358) * ITEM_SIZE_MULT;
    itemH = itemW * JAR_ASPECT;
    if (itemH > vh * 0.72) {
      itemH = vh * 0.72;
      itemW = itemH / JAR_ASPECT;
    }
    totalLen = count * slotW;
    waveLen = 3 * slotW;
    wrapPad = itemW * 2;
    root.style.setProperty("--jar-item-w", `${itemW}px`);
    root.style.setProperty("--jar-item-h", `${itemH}px`);
    root.style.setProperty("--jar-marquee-h", `${Math.min(itemH * 1.35, vh * 0.95)}px`);
    const rootRect = root.getBoundingClientRect();
    const trackRect = track.getBoundingClientRect();
    trackCx = trackRect.left + trackRect.width / 2 - rootRect.left;
    trackCy = trackRect.top + trackRect.height / 2 - rootRect.top;
    const angle = ((Number.parseFloat(getComputedStyle(root).getPropertyValue("--jar-marquee-angle")) || 0) * Math.PI) / 180;
    cosA = Math.cos(angle);
    sinA = Math.sin(angle);
  };
  layout();

  const labels = createLabelRecords(items, () => hoverMq.matches);
  let renderer: JarRenderer | null = null;
  let alive = true;
  let introStart = -1;
  const markIntro = () => { if (introStart < 0) introStart = performance.now(); };
  const introFallback = window.setTimeout(markIntro, (opts.labelDelayMs ?? 120) + 1200);

  const threeTimer = window.setTimeout(async () => {
    try {
      const THREE = await import("three");
      if (!alive) return;
      renderer = createJarWebGLRenderer(THREE, () => labels.forEach((l) => (l.needsRender = true)));
      renderer.resize(labels.map((l) => l.canvas));
      let pending = labels.length;
      if (!pending) return markIntro();
      labels.forEach((l) => {
        if (!renderer) return;
        l.jar = renderer.createMaterial(
          l.labelUrl,
          () => { l.labelReady = true; l.needsRender = true; if (--pending <= 0) markIntro(); },
          () => { if (--pending <= 0) markIntro(); },
        );
      });
    } catch { markIntro(); }
  }, opts.labelDelayMs ?? 120);

  const input = attachMarqueeInput(root, wrap, () => {
    layout();
    renderer?.resize(labels.map((l) => l.canvas));
  });

  let scroll = 0, velocity = 0, lastTime = performance.now(), lastMotionTime = -1;
  let hoverStrength = 0, parX = 0, parY = 0;
  const startTime = performance.now();
  const slotX = (index: number, offset: number) => {
    let c = (index * slotW + itemW / 2 + offset + wrapPad) % totalLen;
    if (c < 0) c += totalLen;
    return c - wrapPad;
  };

  let raf = 0;
  const frame = (now: number) => {
    if (!alive) return;
    const dt = Math.min(1 / 30, Math.max(0, (now - lastTime) / 1000));
    lastTime = now;
    const { target, dragging, pointerInside, pointerX, pointerY } = input.state;
    const motionOk = !reducedMq.matches;
    const hoverActive = motionOk && pointerInside && hoverMq.matches;
    let px = 0, py = 0;
    if (hoverActive || hoverStrength > 0) {
      const rect = root.getBoundingClientRect();
      px = pointerX - rect.left;
      py = pointerY - rect.top;
      if (hoverActive && rect.width > 0 && rect.height > 0) {
        const k = 1 - Math.exp(-4 * dt);
        parX += (Math.max(-1, Math.min(1, (px / rect.width) * 2 - 1)) - parX) * k;
        parY += (Math.max(-1, Math.min(1, (py / rect.height) * 2 - 1)) - parY) * k;
      }
    }
    hoverStrength += ((hoverActive ? 1 : 0) - hoverStrength) * (1 - Math.exp(-3 * dt));
    if (!hoverActive && hoverStrength < 0.001) hoverStrength = 0;
    const parallaxX = parX * hoverStrength;
    const parallaxY = parY * hoverStrength;
    root.style.setProperty("--jar-parallax-x", parallaxX.toFixed(4));
    root.style.setProperty("--jar-parallax-y", parallaxY.toFixed(4));

    const prevScroll = scroll;
    scroll += (target - scroll) * (1 - Math.exp(-(dragging ? 11 : 2.3) * dt));
    if (Math.abs(target - scroll) < 0.05) scroll = target;
    velocity = dt > 0 ? (scroll - prevScroll) / dt : 0;

    const vw = window.innerWidth;
    root.style.setProperty("--jar-circle-rotation", `${scroll * (vw <= 480 ? -0.03 : -0.012)}deg`);
    const speed = Math.abs(velocity);
    if (dragging || speed > MOTION_THRESHOLD) lastMotionTime = now;
    const hoverCalm = !dragging && speed <= slotW * 1.4;
    const vNorm = Math.min(1, speed / 2400);
    const velScale = 1 - vNorm * vNorm * 0.05;
    const velBlur = vNorm * vNorm * (vw <= 480 ? 1.6 : 3.2);

    const shapeT = easeOutCubic(Math.min(1, Math.max(0, now - startTime) / INTRO_MS));
    root.style.setProperty("--jar-shape-intro-opacity", `${shapeT}`);
    root.style.setProperty("--jar-shape-intro-y", `${(1 - shapeT) * INTRO_RISE * 0.42}px`);
    root.style.setProperty("--jar-badge-intro-opacity", `${shapeT}`);
    root.style.setProperty("--jar-badge-intro-y", `${(1 - shapeT) * INTRO_RISE * 0.22}px`);
    root.style.setProperty("--jar-badge-intro-rotation", `${(1 - shapeT) * BADGE_INTRO_ROTATION}deg`);

    labels.forEach((a, i) => {
      const cx = slotX(i, scroll);
      const q = cx / vw;
      const warped = (q + 0.55 * 0.16 * Math.tanh((q - 0.5) / 0.16)) * vw;
      const bell = q >= 0 && q <= 1 ? Math.sin(q * Math.PI) : 0;
      const edge = slotW > 0 ? Math.abs(q - 0.5) / (slotW / vw) : 0;
      const scale = (SCALE_MIN + bell * (SCALE_MAX - SCALE_MIN)) * (1 - EDGE_SHRINK * Math.min(1, edge));
      const brightness = BRIGHT_MIN + bell * (BRIGHT_MAX - BRIGHT_MIN);
      const intro = easeOutCubic(introStart < 0 ? 1 : Math.min(1, Math.max(0, now - introStart) / INTRO_MS));
      const rise = (1 - intro) * INTRO_RISE;
      const rot = Math.sin(((i * slotW + scroll) / waveLen) * Math.PI * 2) * ROT_AMPLITUDE;
      const yOff = Y_OFFSETS[i % Y_OFFSETS.length] * itemH;
      const cxPos = trackCx + (warped - vw / 2) * cosA - (yOff + rise) * sinA;
      const cyPos = trackCy + (warped - vw / 2) * sinA + (yOff + rise) * cosA;

      let turnT = motionOk ? -Math.max(-1, Math.min(1, velocity / 2400)) * 38 : 0;
      let leanT = -Math.sign(velocity) * vNorm * 6;
      let liftT = 0, pullXT = 0, pullYT = 0;
      if (hoverStrength > 0) {
        const along = (px - cxPos) * cosA + (py - cyPos) * sinA;
        const across = -(px - cxPos) * sinA + (py - cyPos) * cosA;
        const radius = itemW * 1.6;
        const gauss = Math.exp(-((along * along + across * across) / (radius * radius)));
        const tAlong = Math.tanh(along / radius);
        const strength = hoverStrength * (0.3 + 0.7 * gauss);
        const sf = scale / SCALE_MAX;
        turnT += tAlong * 30 * strength;
        leanT += tAlong * 5 * gauss * hoverStrength;
        liftT = 0.05 * gauss * hoverStrength;
        pullXT = tAlong * 16 * gauss * hoverStrength + (parallaxX * cosA + parallaxY * sinA) * 26 * sf;
        pullYT = Math.tanh(across / (itemH * 0.8)) * 16 * gauss * hoverStrength + (-parallaxX * sinA + parallaxY * cosA) * 26 * sf;
      }
      const stiffness = SPRING_STIFFNESS * (0.85 + 0.3 * ((i * 0.618034) % 1));
      stepSpring(a.turn, turnT, stiffness, dt);
      stepSpring(a.lean, leanT, stiffness, dt);
      stepSpring(a.lift, liftT, stiffness, dt);
      stepSpring(a.pullX, pullXT, stiffness, dt);
      stepSpring(a.pullY, pullYT, stiffness, dt);

      a.element.style.transform = `translate(${warped - itemW / 2 + a.pullX.value}px, ${yOff + rise + a.pullY.value}px) rotate(${rot + a.lean.value}deg) scale(${scale * (INTRO_SCALE + intro * (1 - INTRO_SCALE)) * velScale * (1 + a.lift.value)})`;
      a.element.style.opacity = `${intro}`;
      a.element.style.filter = `brightness(${brightness}) blur(${(Math.min(vw <= 480 ? 2 : 4, edge * edge) + velBlur).toFixed(2)}px)`;

      let spin = 0;
      if (!hoverCalm || !a.isPointerOver) a.hoverDwellStart = -1;
      else if (a.hoverDwellStart < 0) a.hoverDwellStart = now;
      if (hoverMq.matches && a.isPointerOver && a.hoverQueued && a.cycleStart < 0 && a.hoverDwellStart >= 0 && (a.pointerEnterTime > lastMotionTime || now - a.hoverDwellStart >= HOVER_DWELL_MS)) {
        a.cycleStart = now;
        a.hoverQueued = false;
      }
      if (hoverMq.matches && a.cycleStart >= 0) {
        const elapsed = (now - a.cycleStart) / 1000;
        if (elapsed >= SPIN_DURATION) a.cycleStart = -1;
        else spin = easeInOutQuint(elapsed / SPIN_DURATION);
      }
      const offset = FRONT_ROT / 360 - spin - intro - Math.round(a.turn.value / 360 / 0.0005) * 0.0005;
      if (renderer && a.jar && a.labelReady && (a.needsRender || (cx + itemW > 0 && cx - itemW < vw && a.renderedOffset !== offset))) {
        renderer.render(a.jar, offset);
        renderer.blit(a.ctx);
        a.renderedOffset = offset;
        a.needsRender = false;
      }
    });
    raf = requestAnimationFrame(frame);
  };
  raf = requestAnimationFrame(frame);

  return {
    destroy: () => {
      alive = false;
      window.clearTimeout(threeTimer);
      window.clearTimeout(introFallback);
      cancelAnimationFrame(raf);
      input.destroy();
      labels.forEach((l) => { l.teardown(); l.jar?.dispose(); });
      renderer?.dispose();
    },
  };
}

section/orchard-legal-document.code:
"use client";

import type { ReactNode } from "react";
import styles from "./styles.module.css";

export interface OrchardLegalTable {
  head: string[];
  rows: string[][];
}

export interface OrchardLegalAction {
  label: string;
  onClick?: () => void;
}

export interface OrchardLegalSection {
  heading: string;
  /** Rich paragraphs (inline links and emphasis allowed). */
  paragraphs?: ReactNode[];
  bullets?: ReactNode[];
  /** Paragraphs rendered after the bullet list and the table. */
  after?: ReactNode[];
  table?: OrchardLegalTable;
  /** Pill button rendered after the content, e.g. "Edit cookie preferences". */
  action?: OrchardLegalAction;
}

export interface OrchardLegalDocumentProps {
  id?: string;
  title?: string;
  /** Small muted line under the title, e.g. the last update date. */
  meta?: string;
  sections?: OrchardLegalSection[];
  ariaLabel?: string;
  className?: string;
}

const DEFAULT_SECTIONS: OrchardLegalSection[] = [
  {
    heading: "1. Data controller",
    paragraphs: [
      <>
        Example Orchard Ltd., 12 Example Street, 00100 Sample City. For any request about your personal data:{" "}
        <a href="mailto:hello@example.com">hello@example.com</a>.
      </>,
    ],
  },
  {
    heading: "2. Cookies we use",
    table: {
      head: ["Name", "Purpose", "Category", "Duration"],
      rows: [
        ["session", "Keeps the page language between visits.", "Necessary", "Session"],
        ["analytics", "Counts anonymous visits.", "Analytics", "13 months"],
      ],
    },
    action: { label: "Edit cookie preferences" },
  },
];

export function OrchardLegalDocument({
  id,
  title = "Privacy & Cookie Policy",
  meta = "Last updated: 1 January 2026",
  sections = DEFAULT_SECTIONS,
  ariaLabel,
  className,
}: OrchardLegalDocumentProps) {
  return (
    <div id={id} className={className ? `${styles.legal} ${className}` : styles.legal} aria-label={ariaLabel}>
      <div className={styles.inner}>
        <h1 className={styles.title}>{title}</h1>
        {meta ? <p className={styles.meta}>{meta}</p> : null}
        {sections.map((section, i) => (
          <section key={i} className={styles.section}>
            <h2>{section.heading}</h2>
            {section.paragraphs?.map((p, j) => <p key={j}>{p}</p>)}
            {section.bullets?.length ? (
              <ul>
                {section.bullets.map((b, j) => (
                  <li key={j}>{b}</li>
                ))}
              </ul>
            ) : null}
            {section.table ? (
              <div className={styles.tableWrap}>
                <table className={styles.table}>
                  <thead>
                    <tr>
                      {section.table.head.map((h) => (
                        <th key={h}>{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {section.table.rows.map((row, r) => (
                      <tr key={r}>
                        {row.map((cell, c) => (
                          <td key={c}>{cell}</td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : null}
            {section.after?.map((p, j) => <p key={`a${j}`}>{p}</p>)}
            {section.action ? (
              <p>
                <button type="button" className={styles.button} onClick={section.action.onClick}>
                  {section.action.label}
                </button>
              </p>
            ) : null}
          </section>
        ))}
      </div>
    </div>
  );
}

