extraFiles.product-slider.tsx:
"use client";

import { useCallback, useEffect, useRef, useState, type MouseEvent, type PointerEvent } from "react";
import {
  OrchardJarSlideCard,
  type OrchardJarSlideCardProps,
} from "@registry/ui/orchard-jar-slide-card/component";
import styles from "./styles.module.css";

export type OrchardProductSlideItem = Omit<
  OrchardJarSlideCardProps,
  "dragging" | "onCardClick" | "onHoverChange" | "className"
>;

interface DragState {
  pointerId: number;
  startX: number;
  startY: number;
  startScroll: number;
  lastX: number;
  lastTime: number;
  distance: number;
  velocity: number;
  momentum: number;
  current: number;
  target: number;
  tick: number;
  animating: boolean;
  lockedAxis: "" | "x" | "y";
}

const FOLLOW = 0.075;
const FRICTION = 0.92;
const THROW = 18;
const DRAG_THRESHOLD = 8;

const maxScroll = (el: HTMLElement) => Math.max(0, el.scrollWidth - el.clientWidth);
const clampScroll = (el: HTMLElement, v: number) => Math.max(0, Math.min(maxScroll(el), v));

export function OrchardProductSliderRail({
  items,
  inline = false,
  onSlideClick,
}: {
  items: OrchardProductSlideItem[];
  inline?: boolean;
  onSlideClick?: (id: string, event: MouseEvent<HTMLAnchorElement>) => void;
}) {
  const trackRef = useRef<HTMLDivElement>(null);
  const [dragging, setDragging] = useState(false);
  const draggingRef = useRef(false);
  const suppressClick = useRef(false);
  const st = useRef<DragState>({
    pointerId: -1,
    startX: 0,
    startY: 0,
    startScroll: 0,
    lastX: 0,
    lastTime: 0,
    distance: 0,
    velocity: 0,
    momentum: 0,
    current: 0,
    target: 0,
    tick: 0,
    animating: false,
    lockedAxis: "",
  });

  const scrollable = items.length >= 5;

  const frame = useCallback(function frame() {
    const e = st.current;
    const el = trackRef.current;
    e.tick = 0;
    if (!el) return;
    if (!draggingRef.current && Math.abs(e.momentum) > 0.05) {
      const next = clampScroll(el, e.target + e.momentum);
      if (Math.abs(next - e.target) < 0.05) {
        e.momentum = 0;
      } else {
        e.target = next;
        e.momentum *= FRICTION;
        if (Math.abs(e.momentum) < 0.05) e.momentum = 0;
      }
    }
    e.current += (e.target - e.current) * FOLLOW;
    if (Math.abs(e.target - e.current) < 0.5) e.current = e.target;
    el.scrollLeft = e.current;
    if (draggingRef.current || Math.abs(e.target - e.current) >= 0.5 || Math.abs(e.momentum) > 0.05) {
      e.tick = requestAnimationFrame(frame);
      return;
    }
    e.animating = false;
  }, []);

  const kick = () => {
    const e = st.current;
    if (!e.tick) {
      e.animating = true;
      e.tick = requestAnimationFrame(frame);
    }
  };

  useEffect(() => {
    const state = st.current;
    return () => {
      if (state.tick) cancelAnimationFrame(state.tick);
    };
  }, []);

  const onPointerDown = (ev: PointerEvent<HTMLDivElement>) => {
    const el = trackRef.current;
    if (!el || !scrollable || ev.pointerType !== "mouse" || ev.button !== 0) return;
    const e = st.current;
    e.pointerId = ev.pointerId;
    e.startX = ev.clientX;
    e.startY = ev.clientY;
    e.startScroll = el.scrollLeft;
    e.lastX = ev.clientX;
    e.lastTime = ev.timeStamp || performance.now();
    e.distance = 0;
    e.velocity = 0;
    e.momentum = 0;
    e.current = el.scrollLeft;
    e.target = el.scrollLeft;
    e.lockedAxis = "";
    draggingRef.current = true;
    setDragging(true);
    el.setPointerCapture?.(ev.pointerId);
  };

  const onPointerMove = (ev: PointerEvent<HTMLDivElement>) => {
    const el = trackRef.current;
    const e = st.current;
    if (!el || !draggingRef.current || ev.pointerId !== e.pointerId) return;
    const dx = ev.clientX - e.startX;
    const dy = ev.clientY - e.startY;
    if (!e.lockedAxis) {
      if (Math.abs(dx) < 4 && Math.abs(dy) < 4) return;
      e.lockedAxis = Math.abs(dx) >= Math.abs(dy) ? "x" : "y";
    }
    if (e.lockedAxis !== "x") return;
    const now = ev.timeStamp || performance.now();
    const dt = Math.max(1, now - e.lastTime);
    const v = (ev.clientX - e.lastX) / dt;
    e.velocity = e.velocity * 0.76 + v * 0.24;
    e.lastX = ev.clientX;
    e.lastTime = now;
    e.distance = Math.max(e.distance, Math.abs(dx));
    e.target = clampScroll(el, e.startScroll - dx);
    kick();
  };

  const onPointerUp = (ev: PointerEvent<HTMLDivElement>) => {
    const el = trackRef.current;
    const e = st.current;
    if (!draggingRef.current || (e.pointerId !== -1 && ev.pointerId !== e.pointerId)) return;
    draggingRef.current = false;
    setDragging(false);
    el?.releasePointerCapture?.(ev.pointerId);
    e.pointerId = -1;
    e.momentum = -e.velocity * THROW;
    kick();
    if (e.distance > DRAG_THRESHOLD) {
      suppressClick.current = true;
      setTimeout(() => {
        suppressClick.current = false;
      }, 0);
    }
  };

  if (!items.length) return null;

  const sliderCls = `${styles.slider} ${inline ? styles.sliderInline : ""}`;
  const trackCls = [
    styles.sliderTrack,
    scrollable ? styles.sliderTrackScroll : "",
    dragging ? styles.sliderTrackDragging : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={sliderCls}>
      <div
        ref={trackRef}
        className={trackCls}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        onClickCapture={(ev) => {
          if (suppressClick.current) {
            ev.preventDefault();
            ev.stopPropagation();
          }
        }}
        onDragStart={(ev) => ev.preventDefault()}
      >
        {items.map((item) => (
          <OrchardJarSlideCard
            key={item.id}
            {...item}
            dragging={dragging}
            onCardClick={onSlideClick}
          />
        ))}
      </div>
    </div>
  );
}

section/orchard-production-ledger.code:
"use client";

import { useEffect, useRef } from "react";
import styles from "./styles.module.css";

export interface OrchardLedgerColumn {
  key: string;
  label: string;
}

export interface OrchardProductionLedgerProps {
  id?: string;
  title?: string;
  /** Shrinks the heading font until it fits on one line of its container. */
  singleLineTitle?: boolean;
  /** Paragraphs under the heading; "\n" inside a paragraph is kept as a line break. */
  description?: string[];
  subtitle?: string;
  columns?: OrchardLedgerColumn[];
  rows?: Array<Record<string, string>>;
  ariaLabel?: string;
  className?: string;
}

const DEFAULT_COLUMNS: OrchardLedgerColumn[] = [
  { key: "product", label: "Product" },
  { key: "availability", label: "Availability" },
];

const DEFAULT_ROWS: Array<Record<string, string>> = [
  { product: "Navel Oranges for Fresh Consumption", availability: "November 20 to January 15" },
  { product: "Blood Oranges for Juicing", availability: "January 15 to February 28" },
  { product: "Sweet Lemons for Fresh Consumption", availability: "November 15 to April 15" },
];

export function OrchardProductionLedger({
  id,
  title = "Citrus Fruits",
  singleLineTitle = false,
  description = [
    "Fragrant and juicy, our citrus fruits are the heart of the orchard. Each fruit has its own season, its own character and its own story.",
  ],
  subtitle = "Crates / Box of 10kg",
  columns = DEFAULT_COLUMNS,
  rows = DEFAULT_ROWS,
  ariaLabel,
  className,
}: OrchardProductionLedgerProps) {
  const titleRef = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    const el = titleRef.current;
    if (!singleLineTitle || !el) return;
    let cancelled = false;
    let raf = 0;
    let ro: ResizeObserver | null = null;
    const fit = () => {
      el.style.fontSize = "";
      const available = el.clientWidth;
      if (!available) return;
      const range = document.createRange();
      range.selectNodeContents(el);
      const text = range.getBoundingClientRect().width;
      const max = available * 0.99;
      if (text > max) {
        const size = Number.parseFloat(getComputedStyle(el).fontSize);
        el.style.fontSize = `${((size * max) / text).toFixed(2)}px`;
      }
    };
    (async () => {
      await document.fonts?.ready;
      if (cancelled) return;
      fit();
      const parent = el.parentElement;
      if (parent) {
        ro = new ResizeObserver(() => {
          cancelAnimationFrame(raf);
          raf = requestAnimationFrame(fit);
        });
        ro.observe(parent);
      }
    })();
    return () => {
      cancelled = true;
      cancelAnimationFrame(raf);
      ro?.disconnect();
      el.style.fontSize = "";
    };
  }, [singleLineTitle, title]);

  if (!(title || subtitle || description.length || rows.length)) return null;
  const tableCls = `${styles.table} ${columns.length === 3 ? styles.cols3 : styles.cols2}`;

  return (
    <section
      id={id}
      className={className ? `${styles.section} ${className}` : styles.section}
      aria-label={ariaLabel ?? title}
    >
      <div className={styles.container}>
        <div className={styles.grid}>
          <div className={styles.inner}>
            {title ? (
              <h2 ref={titleRef} className={singleLineTitle ? `${styles.title} ${styles.titleSingle}` : styles.title}>
                {title}
              </h2>
            ) : null}
            {description.length ? (
              <div className={styles.text}>
                {description.map((p, i) => (
                  <p key={i}>{p}</p>
                ))}
              </div>
            ) : null}
            {subtitle ? <h3 className={styles.subtitle}>{subtitle}</h3> : null}
            {rows.length ? (
              <div className={tableCls} role="table" aria-label={title}>
                <div className={`${styles.row} ${styles.rowHead}`} role="row">
                  {columns.map((col) => (
                    <span key={col.key} role="columnheader" className={styles.cell}>
                      {col.label}
                    </span>
                  ))}
                </div>
                {rows.map((row, i) => (
                  <div key={i} className={styles.row} role="row">
                    {columns.map((col) => (
                      <span key={col.key} role="cell" className={styles.cell}>
                        {row[col.key] ?? ""}
                      </span>
                    ))}
                  </div>
                ))}
              </div>
            ) : null}
          </div>
        </div>
      </div>
    </section>
  );
}

