extraFiles.stack-motion.ts:
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

export interface StackStyleClasses {
  sideLeft: string;
  sideRight: string;
  cards: string;
  stage: string;
  cardStack: string;
  mediaImg: string;
}

export function initProposalStackMotion(root: HTMLElement, s: StackStyleClasses) {
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return null;
  gsap.registerPlugin(ScrollTrigger);

  const ctx = gsap.context(() => {
    const mm = gsap.matchMedia();
    mm.add("(min-width: 1025px)", () => {
      const drift = (sel: string, from: number, to: number) => {
        const el = root.querySelector(sel);
        if (!el) return;
        gsap.fromTo(
          el,
          { y: from },
          {
            y: to,
            ease: "none",
            scrollTrigger: { trigger: root, start: "top bottom", end: "bottom top", scrub: true },
          },
        );
      };
      drift(`.${s.sideLeft}`, -110, 110);
      drift(`.${s.sideRight}`, 110, -110);
    });

    mm.add("(min-width: 481px)", () => {
      const wrap = root.querySelector<HTMLElement>(`.${s.cards}`);
      const stage = root.querySelector<HTMLElement>(`.${s.stage}`);
      const stack = Array.from(root.querySelectorAll<HTMLElement>(`.${s.cardStack}`));
      if (!wrap || !stage || stack.length < 2) return;
      const offscreen = () => {
        const h = stack[0].offsetHeight || 1;
        return ((window.innerHeight + h) / 2 / h) * 100 + 2;
      };
      const img = (card: HTMLElement) => card.querySelector<HTMLElement>(`.${s.mediaImg}`);
      stack.forEach((card, i) => {
        gsap.set(card, {
          zIndex: stack.length - i,
          yPercent: i === 0 ? 0 : offscreen(),
          autoAlpha: i <= 1 ? 1 : 0,
          scale: 1,
          rotationZ: 0,
          rotationX: 0,
          xPercent: 0,
          "--card-shade": 0,
        });
      });
      const firstImg = img(stack[0]);
      if (firstImg) {
        gsap.fromTo(
          firstImg,
          { yPercent: -10 },
          { yPercent: 0, ease: "none", scrollTrigger: { trigger: wrap, start: "top bottom", end: "top top", scrub: true } },
        );
      }
      const tl = gsap.timeline({
        defaults: { ease: "none", duration: 1 },
        scrollTrigger: {
          trigger: wrap,
          start: "top top",
          end: () => `+=${(stack.length - 1) * window.innerHeight}`,
          scrub: true,
          pin: stage,
          pinSpacing: false,
          invalidateOnRefresh: true,
        },
      });
      stack.slice(0, -1).forEach((card, i) => {
        const next = stack[i + 1];
        const nextImg = img(next);
        tl.set(next, { zIndex: stack.length + i + 1 }, i)
          .set(next, { autoAlpha: 1 }, i)
          .fromTo(next, { yPercent: () => offscreen() }, { yPercent: 0 }, i)
          .to(
            card,
            { scale: 0.85, rotationZ: -3.8, rotationX: 8, xPercent: -0.8, yPercent: 0, "--card-shade": 0.26 },
            i,
          );
        if (nextImg) tl.fromTo(nextImg, { yPercent: -10 }, { yPercent: 0 }, i);
      });
    });
  }, root);

  return ctx;
}

section/orchard-top-header.code:
"use client";

import { useEffect, useId, useRef, useState, type MouseEvent, type ReactNode } from "react";
import { OrchardRollingToggle } from "@registry/ui/orchard-rolling-toggle/component";
import { DefaultBrandCrest } from "./default-crest";
import { OrchardNavOverlay, type OrchardHeaderNavItem } from "./nav-overlay";
import styles from "./styles.module.css";

export type { OrchardHeaderNavItem };

export interface OrchardLanguageOption {
  code: string;
  label: string;
  href?: string;
}

export interface OrchardTopHeaderProps {
  id?: string;
  brandName?: string;
  brandSubtitle?: string;
  brandHref?: string;
  brandAriaLabel?: string;
  brandLogo?: ReactNode;
  showLangSwitcher?: boolean;
  languages?: OrchardLanguageOption[];
  activeLang?: string;
  langSwitcherAriaLabel?: string;
  onLangChange?: (code: string) => void;
  menuLabel?: string;
  closeLabel?: string;
  navOpen?: boolean;
  onNavOpenChange?: (open: boolean) => void;
  primaryNav?: OrchardHeaderNavItem[];
  secondaryNav?: OrchardHeaderNavItem[];
  legalLinks?: OrchardHeaderNavItem[];
  navAriaLabel?: string;
  onNavigate?: (href: string, event: MouseEvent<HTMLAnchorElement>) => void;
  theme?: "dark" | "light";
  autoCompactOnScroll?: boolean;
  autoHideOnScroll?: boolean;
  enableOverlay?: boolean;
  className?: string;
}

const DEFAULT_LANGUAGES: OrchardLanguageOption[] = [
  { code: "it", label: "IT", href: "#lang-it" },
  { code: "en", label: "EN", href: "#lang-en" },
];

const DEFAULT_PRIMARY_NAV: OrchardHeaderNavItem[] = [
  { label: "Home", href: "#top" },
  { label: "Pantry", href: "#pantry", active: true },
  { label: "Harvest", href: "#harvest" },
  { label: "About", href: "#about" },
  { label: "Contact", href: "#contact" },
];

const DEFAULT_SECONDARY_NAV: OrchardHeaderNavItem[] = [
  { label: "Tasting Room", href: "#experiences" },
  { label: "Instagram", href: "https://instagram.com", external: true },
];

export function OrchardTopHeader({
  id,
  brandName = "SOLARA",
  brandSubtitle = "Orchard",
  brandHref = "#top",
  brandAriaLabel,
  brandLogo,
  showLangSwitcher = true,
  languages = DEFAULT_LANGUAGES,
  activeLang = "en",
  langSwitcherAriaLabel = "Language switcher",
  onLangChange,
  menuLabel = "menu",
  closeLabel = "close",
  navOpen: controlledOpen,
  onNavOpenChange,
  primaryNav = DEFAULT_PRIMARY_NAV,
  secondaryNav = DEFAULT_SECONDARY_NAV,
  legalLinks = [],
  navAriaLabel = "Main navigation",
  onNavigate,
  theme = "dark",
  autoCompactOnScroll = true,
  autoHideOnScroll = false,
  enableOverlay = true,
  className,
}: OrchardTopHeaderProps) {
  const overlayId = useId();
  const headerRef = useRef<HTMLElement>(null);
  const brandRef = useRef<HTMLDivElement>(null);
  const fullGroupRef = useRef<HTMLSpanElement>(null);
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false);
  const [compact, setCompact] = useState(false);
  const [hidden, setHidden] = useState(false);

  const isControlled = controlledOpen !== undefined;
  const open = isControlled ? controlledOpen : uncontrolledOpen;

  const setOpen = (next: boolean) => {
    if (!isControlled) setUncontrolledOpen(next);
    onNavOpenChange?.(next);
  };

  useEffect(() => {
    const syncBrandHeight = () => {
      const brand = brandRef.current;
      const group = fullGroupRef.current;
      if (!brand || !group) return;
      const h = group.getBoundingClientRect().height;
      if (h) brand.style.height = `${h}px`;
    };
    syncBrandHeight();

    let lastY = window.scrollY;
    const onScroll = () => {
      const y = Math.max(0, window.scrollY);
      if (autoCompactOnScroll) setCompact(y > 33);
      if (autoHideOnScroll && y > 200) {
        if (y - lastY > 6) setHidden(true);
        else if (lastY - y > 6) setHidden(false);
      } else {
        setHidden(false);
      }
      lastY = y;
    };

    window.addEventListener("resize", syncBrandHeight, { passive: true });
    if (autoCompactOnScroll || autoHideOnScroll) {
      window.addEventListener("scroll", onScroll, { passive: true });
    }
    return () => {
      window.removeEventListener("resize", syncBrandHeight);
      window.removeEventListener("scroll", onScroll);
    };
  }, [autoCompactOnScroll, autoHideOnScroll]);

  const headerClasses = [
    styles.header,
    compact && !open ? styles.isCompact : "",
    hidden && !open ? styles.isHidden : "",
    open ? styles.isNavOpen : "",
    theme === "light" ? styles.isLight : "",
    className ?? "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <>
      <header
        id={id}
        ref={headerRef}
        className={headerClasses}
        data-header-theme={theme}
        data-header-logo={compact && !open ? "compact" : "full"}
      >
        <div className={styles.bar}>
          <div className={`${styles.side} ${styles.sideStart}`}>
            {showLangSwitcher && languages.length ? (
              <nav className={styles.langSwitcher} aria-label={langSwitcherAriaLabel}>
                {languages.map((lang) => {
                  const isActive = lang.code === activeLang;
                  const cls = `${styles.langItem} ${isActive ? styles.langActive : ""}`;
                  if (onLangChange) {
                    return (
                      <button
                        key={lang.code}
                        type="button"
                        className={cls}
                        aria-current={isActive ? "true" : undefined}
                        onClick={() => onLangChange(lang.code)}
                      >
                        {lang.label}
                      </button>
                    );
                  }
                  return (
                    <a
                      key={lang.code}
                      href={lang.href ?? `#${lang.code}`}
                      className={cls}
                      aria-current={isActive ? "true" : undefined}
                    >
                      {lang.label}
                    </a>
                  );
                })}
              </nav>
            ) : null}
          </div>

          <div className={styles.center}>
            <div ref={brandRef} className={styles.brand}>
              <a
                href={brandHref}
                className={styles.brandLink}
                aria-label={brandAriaLabel ?? `${brandName} ${brandSubtitle}`.trim()}
                onClick={onNavigate ? (e) => onNavigate(brandHref, e) : undefined}
              >
                <span ref={fullGroupRef} className={styles.logoSvg}>
                  {brandLogo ?? (
                    <DefaultBrandCrest
                      brandName={brandName}
                      brandSubtitle={brandSubtitle}
                      iconClassName={styles.logoIcon}
                      wordmarkClassName={styles.logoWordmark}
                      subClassName={styles.logoSub}
                    />
                  )}
                </span>
              </a>
            </div>
          </div>

          <div className={`${styles.side} ${styles.sideEnd}`}>
            <OrchardRollingToggle
              open={open}
              onToggle={() => setOpen(!open)}
              menuLabel={menuLabel}
              closeLabel={closeLabel}
              theme={open ? "dark" : theme}
              controlsId={enableOverlay ? overlayId : undefined}
            />
          </div>
        </div>
      </header>

      {enableOverlay ? (
        <OrchardNavOverlay
          id={overlayId}
          open={open}
          primaryNav={primaryNav}
          secondaryNav={secondaryNav}
          legalLinks={legalLinks}
          navAriaLabel={navAriaLabel}
          onClose={() => setOpen(false)}
          onNavigate={onNavigate}
        />
      ) : null}
    </>
  );
}

section/orchard-top-header.stylesCss:
.header {
  inset: 0 0 auto;
  line-height: 1.3;
  padding: 30px 30px;
  pointer-events: none;
  position: fixed;
  transform: translateZ(0);
  transition:
    transform 0.8s cubic-bezier(0.19, 1, 0.22, 1),
    background-color 0.35s cubic-bezier(0.19, 1, 0.22, 1);
  width: 100%;
  z-index: 900;
}

.isHidden {
  transform: translate3d(0, calc(-100% - 40px), 0);
}

.solidBg {
  background-color: var(--rk-surface-elevated);
  inset: 0 0 auto;
  opacity: 0;
  pointer-events: none;
  position: fixed;
  transform: translateZ(0);
  transition:
    transform 0.8s cubic-bezier(0.19, 1, 0.22, 1),
    opacity 0.35s cubic-bezier(0.19, 1, 0.22, 1);
  z-index: 790;
}

.solidBgVisible {
  opacity: 1;
}

.solidBgHidden {
  transform: translate3d(0, calc(-100% - 40px), 0);
}

.bar {
  align-items: flex-start;
  display: flex;
  gap: 32px;
  justify-content: space-between;
  position: relative;
}

.side {
  align-items: flex-start;
  display: flex;
  flex: 1 1 0;
  min-width: 0;
  pointer-events: auto;
}

.sideEnd {
  justify-content: flex-end;
}

.center {
  display: flex;
  justify-content: center;
  left: 50%;
  pointer-events: none;
  position: absolute;
  top: 0;
  transform: translate(-50%);
}

.brand {
  display: inline-block;
  overflow: hidden;
  pointer-events: auto;
  position: relative;
  transition: height 0.45s cubic-bezier(0.19, 1, 0.22, 1);
  width: 135px;
}

.brandLink {
  color: inherit;
  display: block;
  text-decoration: none;
}

.brandLink:focus-visible {
  border-radius: var(--rk-radius-sm);
  box-shadow: 0 0 0 5px var(--rk-bg);
  outline: 2px solid var(--rk-fg);
