extraFiles.stats-physics.ts:
import type { Body } from "matter-js";
import {
  BALL_OPTIONS,
  layoutPitWorld,
  nudgeNearbyBalls,
  randomBallRadius,
  renderStatsPit,
  seedColumnPiles,
  type BallState,
  type MatterModule,
  type PitMetrics,
} from "./stats-renderer";
import { PHYSICS_CONFIG, buildColumnTextures, easeOutBack, type StatColumn } from "./stats-textures";

export interface StatsPhysicsOptions {
  canvas: HTMLCanvasElement;
  gooCanvas: HTMLCanvasElement;
  columns: StatColumn[];
  visibleRef: { current: boolean };
  focusedRef: { current: boolean };
  countRefs: { current: (HTMLSpanElement | null)[] };
  reducedMotion: boolean;
}

export function startStatsPhysics(Matter: MatterModule, opts: StatsPhysicsOptions): () => void {
  const { canvas, gooCanvas, columns, visibleRef, focusedRef, countRefs, reducedMotion } = opts;
  const ctx = canvas.getContext("2d");
  const gooCtx = gooCanvas.getContext("2d");
  if (!ctx || !gooCtx) return () => {};

  const colCount = Math.max(1, columns.length);
  const { Engine, Composite, Bodies, Body: MatterBody, Events } = Matter;
  const engine = Engine.create({ enableSleeping: true });
  engine.gravity.y = 1.4;
  engine.positionIterations = 12;
  engine.velocityIterations = 8;

  const textures = buildColumnTextures(colCount);
  const balls: Body[] = [];
  const ballState = new WeakMap<Body, BallState>();
  const dyingScratch: Body[] = [];
  const targetCounts = new Array<number>(colCount).fill(0);
  const shownCounts = new Array<number>(colCount).fill(0);
  let metrics: PitMetrics = { width: 0, height: 0, dpr: 1, surfaceY: 0, baseRadius: 24, floor: null, walls: [] };

  const columnOf = (x: number) => Math.min(colCount - 1, Math.max(0, Math.floor(x / (metrics.width / colCount))));
  const removeBall = (ball: Body) => {
    Composite.remove(engine.world, ball);
    const index = balls.indexOf(ball);
    if (index >= 0) balls.splice(index, 1);
    ballState.delete(ball);
  };

  function rebuildWorld() {
    const next = layoutPitWorld(Matter, engine, canvas, gooCanvas, colCount, metrics.walls);
    if (!next) return;
    metrics = next;
    for (const ball of balls) Composite.remove(engine.world, ball);
    balls.length = 0;
    seedColumnPiles({ Matter, engine, columns, metrics, balls, ballState, targetCounts, shownCounts, countRefs, reducedMotion });
  }

  function onBallContact(ball: Body, other: Body) {
    const state = ballState.get(ball);
    if (!state || state.landed || state.dying || !(other === metrics.floor || ballState.get(other)?.landed)) return;
    if (ball.position.y < metrics.surfaceY) {
      state.dying = true;
      state.dieT = 0;
      ball.isSensor = true;
      const side = Math.random() < 0.5 ? -1 : 1;
      MatterBody.setVelocity(ball, { x: side * (5 + Math.random() * 8), y: -(2 + Math.random() * 7) });
      MatterBody.setAngularVelocity(ball, (Math.random() - 0.5) * 0.8);
      return;
    }
    const col = columnOf(ball.position.x);
    state.landed = true;
    state.idx = col;
    targetCounts[col] = Math.min(PHYSICS_CONFIG.maxScore, targetCounts[col] + PHYSICS_CONFIG.scorePerBall);
  }

  Events.on(engine, "collisionStart", (event) => {
    for (const pair of event.pairs) {
      if (ballState.has(pair.bodyA)) onBallContact(pair.bodyA, pair.bodyB);
      if (ballState.has(pair.bodyB)) onBallContact(pair.bodyB, pair.bodyA);
    }
  });

  const paint = (focusedFor: number) =>
    renderStatsPit({ ctx, gooCtx, canvas, metrics, colCount, focusedFor, reducedMotion, balls, ballState, textures });

  rebuildWorld();

  let resizeTimer = 0;
  const onResize = () => {
    clearTimeout(resizeTimer);
    resizeTimer = window.setTimeout(() => {
      if (canvas.clientWidth === metrics.width && canvas.clientHeight === metrics.height) return;
      rebuildWorld();
      if (reducedMotion) paint(2);
    }, 160);
  };

  if (reducedMotion) {
    paint(2);
    window.addEventListener("resize", onResize);
    return () => {
      window.removeEventListener("resize", onResize);
      clearTimeout(resizeTimer);
      Composite.clear(engine.world, false);
      Engine.clear(engine);
    };
  }

  const pointer = { x: 0, y: 0, inside: false, holding: false };
  const pointerVel = { x: 0 };
  let lastPointerX = 0;
  let nextSpawnAt = 0;

  function spawnBall(x: number, yIn: number) {
    const y = Math.min(yIn, metrics.surfaceY - metrics.baseRadius * PHYSICS_CONFIG.radiusMaxFactor * 2);
    const ball = Bodies.circle(x, y, randomBallRadius(metrics.baseRadius), BALL_OPTIONS);
    MatterBody.setVelocity(ball, { x: Math.max(-9, Math.min(9, pointerVel.x * 0.8)), y: 1 + Math.random() });
    ballState.set(ball, { landed: false, scale: 1, dying: false, dieT: 0, idx: -1, popT: PHYSICS_CONFIG.popDuration, popDelay: 0 });
    balls.push(ball);
    Composite.add(engine.world, ball);
    if (balls.length > 260) removeBall(balls[0]);
  }

  const localPoint = (e: PointerEvent) => {
    const r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };
  const onPointerMove = (e: PointerEvent) => {
    const p = localPoint(e);
    pointer.x = p.x;
    pointer.y = p.y;
    pointer.inside = true;
    if (pointer.holding && p.y > metrics.surfaceY) nudgeNearbyBalls(Matter, balls, p.x, p.y, metrics.baseRadius);
  };
  const onPointerLeave = () => { pointer.inside = false; pointer.holding = false; };
  const onPointerDown = (e: PointerEvent) => {
    const p = localPoint(e);
    pointer.x = p.x;
    pointer.y = p.y;
    pointer.inside = true;
    pointer.holding = true;
    if (p.y > metrics.surfaceY) nudgeNearbyBalls(Matter, balls, p.x, p.y, metrics.baseRadius);
    else spawnBall(p.x, p.y);
    nextSpawnAt = performance.now() + PHYSICS_CONFIG.holdSpawnIntervalMs;
  };
  const onPointerUp = () => { pointer.holding = false; };

  canvas.addEventListener("pointermove", onPointerMove);
  canvas.addEventListener("pointerenter", onPointerMove);
  canvas.addEventListener("pointerleave", onPointerLeave);
  canvas.addEventListener("pointerdown", onPointerDown);
  window.addEventListener("pointerup", onPointerUp);
  window.addEventListener("resize", onResize);

  let raf = 0;
  let lastFrame = performance.now();
  let accumulator = 0;
  let focusedFor = 0;
  const stepMs = 1000 / 60;

  const frame = () => {
    const now = performance.now();
    const dt = Math.min(0.05, (now - lastFrame) / 1000);
    lastFrame = now;
    if (!visibleRef.current) { accumulator = 0; raf = requestAnimationFrame(frame); return; }

    pointerVel.x = pointerVel.x * 0.6 + (pointer.x - lastPointerX) * 0.4;
    lastPointerX = pointer.x;
    if ((pointer.holding || pointer.inside) && now >= nextSpawnAt) {
      spawnBall(pointer.x, pointer.y);
      nextSpawnAt = now + (pointer.holding ? PHYSICS_CONFIG.holdSpawnIntervalMs : 500 + Math.random() * 300);
    }

    accumulator += dt * 1000;
    for (let steps = 0; accumulator >= stepMs && steps < 5; steps++) {
      Engine.update(engine, stepMs);
      accumulator -= stepMs;
    }
    if (accumulator > stepMs) accumulator = 0;
    focusedFor = focusedRef.current ? focusedFor + dt : 0;

    for (const ball of balls) {
      const state = ballState.get(ball);
      if (state?.dying) {
        state.dieT += dt;
        state.scale = Math.max(0, 1 - state.dieT / PHYSICS_CONFIG.dieDuration);
        if (state.scale <= 0) dyingScratch.push(ball);
      } else if (focusedRef.current && state && state.popT < PHYSICS_CONFIG.popDuration) {
        if (state.popDelay > 0) state.popDelay -= dt;
        else {
          state.popT = Math.min(PHYSICS_CONFIG.popDuration, state.popT + dt);
          state.scale = easeOutBack(state.popT / PHYSICS_CONFIG.popDuration);
        }
      }
    }
    while (dyingScratch.length) removeBall(dyingScratch.pop()!);

    if (focusedRef.current && focusedFor >= 0.75) {
      for (let col = 0; col < colCount; col++) {
        if (shownCounts[col] === targetCounts[col]) continue;
        shownCounts[col] += (targetCounts[col] - shownCounts[col]) * Math.min(1, dt * 9);
        if (Math.abs(targetCounts[col] - shownCounts[col]) < 0.5) shownCounts[col] = targetCounts[col];
        const el = countRefs.current[col];
        if (el) el.textContent = String(Math.round(shownCounts[col]));
      }
    }

    const settled =
      focusedFor > 1.6 &&
      !pointer.inside &&
      !pointer.holding &&
      balls.every((b) => { const s = ballState.get(b); return Boolean(s && !s.dying && s.popT >= PHYSICS_CONFIG.popDuration && b.isSleeping); }) &&
      shownCounts.every((v, col) => v === targetCounts[col]);

    if (!settled) paint(focusedFor);
    raf = requestAnimationFrame(frame);
  };
  raf = requestAnimationFrame(frame);

  return () => {
    cancelAnimationFrame(raf);
    canvas.removeEventListener("pointermove", onPointerMove);
    canvas.removeEventListener("pointerenter", onPointerMove);
    canvas.removeEventListener("pointerleave", onPointerLeave);
    canvas.removeEventListener("pointerdown", onPointerDown);
    window.removeEventListener("pointerup", onPointerUp);
    window.removeEventListener("resize", onResize);
    clearTimeout(resizeTimer);
    Composite.clear(engine.world, false);
    Engine.clear(engine);
  };
}

extraFiles.stats-renderer.ts:
import type { Body, Engine } from "matter-js";
import {
  PHYSICS_CONFIG,
  drawCover,
  getColumnFallbackColor,
  type StatColumn,
} from "./stats-textures";

export type MatterModule = typeof import("matter-js");

export interface BallState {
  landed: boolean;
  scale: number;
  dying: boolean;
  dieT: number;
  idx: number;
  popT: number;
  popDelay: number;
}

export const BALL_OPTIONS = {
  restitution: 0.3,
  friction: 0.04,
  frictionStatic: 0.2,
  frictionAir: 0.012,
  density: 0.0016,
};

export interface PitMetrics {
  width: number;
  height: number;
  dpr: number;
  surfaceY: number;
  baseRadius: number;
  floor: Body | null;
  walls: Body[];
}

export function layoutPitWorld(
  Matter: MatterModule,
  engine: Engine,
  canvas: HTMLCanvasElement,
  gooCanvas: HTMLCanvasElement,
  colCount: number,
  prevWalls: Body[],
): PitMetrics | null {
  const width = canvas.clientWidth;
  const height = canvas.clientHeight;
  if (!width || !height) return null;

  const { Bodies, Composite } = Matter;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.floor(width * dpr);
  canvas.height = Math.floor(height * dpr);
  gooCanvas.width = canvas.width;
  gooCanvas.height = canvas.height;

  const surfaceY = height * PHYSICS_CONFIG.surfaceYFraction;
  const baseRadius = Math.max(
    15,
    Math.min(
      48,
      Math.sqrt((0.68 * (width / colCount) * (height - surfaceY)) / (PHYSICS_CONFIG.ballsPerColumn * Math.PI)),
    ),
  );

  if (prevWalls.length) Composite.remove(engine.world, prevWalls);
  const floor = Bodies.rectangle(width / 2, height + 40, width + 200, 80, { isStatic: true });
  const walls: Body[] = [
    floor,
    Bodies.rectangle(-40, height / 2, 80, height * 3, { isStatic: true }),
    Bodies.rectangle(width + 40, height / 2, 80, height * 3, { isStatic: true }),
    ...Array.from({ length: colCount - 1 }, (_, i) =>
      Bodies.rectangle(width * ((i + 1) / colCount), height / 2, PHYSICS_CONFIG.dividerWidth, height * 2, {
        isStatic: true,
      }),
    ),
  ];
  Composite.add(engine.world, walls);

  return { width, height, dpr, surfaceY, baseRadius, floor, walls };
}

export function randomBallRadius(baseRadius: number): number {
  return (
    baseRadius *
    (PHYSICS_CONFIG.radiusMinFactor +
      Math.random() * (PHYSICS_CONFIG.radiusMaxFactor - PHYSICS_CONFIG.radiusMinFactor))
  );
}

export function seedColumnPiles(args: {
  Matter: MatterModule;
  engine: Engine;
  columns: StatColumn[];
  metrics: PitMetrics;
  balls: Body[];
  ballState: WeakMap<Body, BallState>;
  targetCounts: number[];
  shownCounts: number[];
  countRefs: { current: (HTMLSpanElement | null)[] };
  reducedMotion: boolean;
}): void {
  const { Matter, engine, columns, metrics, balls, ballState, targetCounts, shownCounts, countRefs, reducedMotion } =
    args;
  const { Bodies, Composite } = Matter;
  const colCount = Math.max(1, columns.length);
  const colW = metrics.width / colCount;

  for (let col = 0; col < colCount; col++) {
    const raw = Math.round(columns[col].target / 11);
    const count = Math.max(PHYSICS_CONFIG.seedMinBalls, Math.min(PHYSICS_CONFIG.seedMaxBalls, raw));
    const left = col * colW + 8;
    const right = (col + 1) * colW - 8;
    let cx = left;
    let cy = metrics.height - 8;
    let rowMax = 0;

    for (let s = 0; s < count; s++) {
      const radius = randomBallRadius(metrics.baseRadius);
      if (cx + radius * 2 > right && cx > left) {
        cx = left;
        cy -= rowMax * 2 * 0.95;
        rowMax = 0;
      }
      const ball = Bodies.circle(cx + radius, cy - radius, radius, BALL_OPTIONS);
      ballState.set(ball, {
        landed: true,
        scale: reducedMotion ? 1 : 0,
        dying: false,
        dieT: 0,
        idx: col,
        popT: reducedMotion ? PHYSICS_CONFIG.popDuration : 0,
        popDelay: reducedMotion ? 0 : 0.85 + s * 0.07 + Math.random() * 0.12,
      });
      balls.push(ball);
      Composite.add(engine.world, ball);
      cx += radius * 2 + 1;
      rowMax = Math.max(rowMax, radius);
    }

    targetCounts[col] = count * PHYSICS_CONFIG.scorePerBall;
    if (reducedMotion) {
      shownCounts[col] = targetCounts[col];
      const el = countRefs.current[col];
      if (el) el.textContent = String(shownCounts[col]);
    }
  }
}

export function nudgeNearbyBalls(
  Matter: MatterModule,
  balls: Body[],
  px: number,
  py: number,
  baseRadius: number,
): void {
  const reach = baseRadius * 3.2;
  for (const ball of balls) {
    const dx = ball.position.x - px;
    const dy = ball.position.y - py;
    const dist = Math.hypot(dx, dy);
    if (dist > 0.1 && dist < reach) {
      Matter.Sleeping.set(ball, false);
      const push = (1 - dist / reach) * 0.018;
      Matter.Body.applyForce(ball, ball.position, { x: (dx / dist) * push, y: (dy / dist) * push - 0.004 });
    }
  }
}

export interface RenderPitArgs {
  ctx: CanvasRenderingContext2D;
  gooCtx: CanvasRenderingContext2D;
  canvas: HTMLCanvasElement;
  metrics: PitMetrics;
  colCount: number;
  focusedFor: number;
  reducedMotion: boolean;
  balls: Body[];
  ballState: WeakMap<Body, BallState>;
  textures: HTMLCanvasElement[];
}

export function renderStatsPit(args: RenderPitArgs): void {
  const { ctx, gooCtx, canvas, metrics, colCount, focusedFor, reducedMotion, balls, ballState, textures } = args;
  const { width, height, dpr, surfaceY, baseRadius } = metrics;
  if (!width || !height) return;

  const ink = getComputedStyle(canvas).color || "currentColor";
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);
  ctx.strokeStyle = ink;
  ctx.globalAlpha = 0.12;
  ctx.lineWidth = 1;
  for (let i = 0; i < colCount - 1; i++) {
    const p = reducedMotion ? 1 : Math.min(1, Math.max(0, (focusedFor - 0.6 - i * 0.14) / 0.6));
    if (p <= 0) continue;
    const eased = 1 - (1 - p) ** 3;
    const x = width * ((i + 1) / colCount);
    ctx.beginPath();
    ctx.moveTo(x, surfaceY);
    ctx.lineTo(x, surfaceY + (height - surfaceY) * eased);
    ctx.stroke();
  }

  ctx.fillStyle = ink;
  for (const ball of balls) {
    const state = ballState.get(ball);
    if (!state || state.landed) continue;
    const r = (ball.circleRadius ?? baseRadius) * state.scale;
    if (r < 0.5) continue;
    ctx.globalAlpha = state.dying ? 0.16 * state.scale : 0.16;
    ctx.beginPath();
    ctx.arc(ball.position.x, ball.position.y, r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  gooCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
  gooCtx.clearRect(0, 0, width, height);
  const colW = width / colCount;
  const lift = baseRadius * PHYSICS_CONFIG.radiusMaxFactor * 3;
  for (let col = 0; col < colCount; col++) {
    const colX = colW * col;
    gooCtx.save();
    gooCtx.beginPath();
    let any = false;
    for (const ball of balls) {
      const state = ballState.get(ball);
      if (!state || !state.landed || state.idx !== col) continue;
      const r = (ball.circleRadius ?? baseRadius) * 1.09 * state.scale;
      if (r < 0.5) continue;
      gooCtx.moveTo(ball.position.x + r, ball.position.y);
      gooCtx.arc(ball.position.x, ball.position.y, r, 0, Math.PI * 2);
      any = true;
    }
    if (any) {
      gooCtx.clip();
      const tex = textures[col];
      if (tex) drawCover(gooCtx, tex, colX, surfaceY - lift, colW, height - surfaceY + lift);
      else {
        gooCtx.fillStyle = getColumnFallbackColor(col);
        gooCtx.fillRect(colX, surfaceY - lift, colW, height - surfaceY + lift);
      }
    }
    gooCtx.restore();
  }
}

extraFiles.stats-textures.ts:
export interface StatColumn {
  key: string;
  label: string;
  target: number;
  subtitle?: string;
}

export const PHYSICS_CONFIG = {
  surfaceYFraction: 0.5,
  ballsPerColumn: 25,
  scorePerBall: 4,
  maxScore: 100,
  seedMinBalls: 5,
  seedMaxBalls: 8,
  dividerWidth: 8,
  holdSpawnIntervalMs: 143,
  dieDuration: 0.38,
  popDuration: 0.42,
  radiusMinFactor: 0.6,
  radiusMaxFactor: 1.45,
} as const;

export const easeOutBack = (t: number): number => {
  const c = 1.70158;
  return 1 + (c + 1) * (t - 1) ** 3 + c * (t - 1) ** 2;
};

const FALLBACK_COLORS = [
  "hsl(12 96% 49%)",
  "hsl(194 84% 80%)",
  "hsl(305 88% 87%)",
  "hsl(217 94% 46%)",
] as const;

const MOBILE_TILE_GRADIENTS = [
  "linear-gradient(155deg, hsl(46 98% 54%) 0%, hsl(46 98% 54%) 26%, hsl(12 96% 49%) 26.5%, hsl(12 96% 49%) 100%)",
  "linear-gradient(104deg, hsl(194 84% 82%) 0%, hsl(194 84% 82%) 46%, hsl(34 22% 45%) 46.5%, hsl(34 22% 45%) 74%, hsl(194 84% 82%) 74.5%)",
  "linear-gradient(112deg, hsl(305 88% 87%) 0%, hsl(305 88% 87%) 40%, hsl(38 22% 46%) 40.5%, hsl(38 22% 46%) 62%, hsl(305 88% 87%) 62.5%)",
  "repeating-linear-gradient(135deg, hsl(217 94% 46%) 0 38px, hsl(200 94% 80%) 38px 62px, hsl(217 94% 46%) 62px 104px)",
] as const;

export function getColumnFallbackColor(index: number): string {
  return FALLBACK_COLORS[index % FALLBACK_COLORS.length];
}

export function getMobileTileGradient(index: number): string {
  return MOBILE_TILE_GRADIENTS[index % MOBILE_TILE_GRADIENTS.length];
}

function paintEmberMotif(ctx: CanvasRenderingContext2D, w: number, h: number) {
  ctx.fillStyle = "hsl(12 96% 49%)";
  ctx.fillRect(0, 0, w, h);

  ctx.fillStyle = "hsl(46 98% 54%)";
  const spikes = 7;
  const step = w / spikes;
  for (let row = 0; row < 3; row++) {
    const yBase = h * (0.28 + row * 0.27);
    ctx.beginPath();
    ctx.moveTo(0, yBase);
    for (let i = 0; i <= spikes; i++) {
      const px = i * step;
      const py = i % 2 === 0 ? yBase - h * 0.14 : yBase + h * 0.05;
      ctx.lineTo(px, py);
    }
    ctx.lineTo(w, yBase + h * 0.08);
    ctx.lineTo(0, yBase + h * 0.08);
    ctx.closePath();
    ctx.fill();
  }

  ctx.fillStyle = "hsl(12 96% 49%)";
  ctx.beginPath();
  ctx.arc(w * 0.5, h * 0.92, w * 0.52, Math.PI, 0);
  ctx.fill();
}

function paintGlacierMotif(ctx: CanvasRenderingContext2D, w: number, h: number) {
  ctx.fillStyle = "hsl(194 84% 82%)";
  ctx.fillRect(0, 0, w, h);

  ctx.fillStyle = "hsl(34 22% 45%)";
  ctx.beginPath();
  ctx.moveTo(w * 0.34, 0);
  ctx.lineTo(w * 0.72, 0);
  ctx.lineTo(w * 0.58, h);
  ctx.lineTo(w * 0.22, h);
  ctx.closePath();
  ctx.fill();

  ctx.beginPath();
  ctx.arc(w * 0.68, h * 0.56, w * 0.24, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = "hsl(194 84% 82%)";
  ctx.beginPath();
  ctx.arc(w * 0.5, h * 0.76, w * 0.17, Math.PI, 0);
  ctx.lineTo(w * 0.67, h);
  ctx.lineTo(w * 0.33, h);
  ctx.closePath();
  ctx.fill();
}

function paintOrchidMotif(ctx: CanvasRenderingContext2D, w: number, h: number) {
  ctx.fillStyle = "hsl(305 88% 87%)";
  ctx.fillRect(0, 0, w, h);

  ctx.fillStyle = "hsl(38 22% 46%)";
  const bands: Array<[number, number, number, number]> = [
    [0.18, 0.14, 0.36, 0.34],
    [0.54, 0.32, 0.28, 0.38],
    [0.24, 0.62, 0.38, 0.26],
    [0.72, 0.72, 0.24, 0.2],
  ];
  for (const [rx, ry, rw, rh] of bands) {
    ctx.beginPath();
    ctx.moveTo(w * rx, h * ry);
    ctx.lineTo(w * (rx + rw), h * ry);
    ctx.lineTo(w * (rx + rw - 0.12), h * (ry + rh));
    ctx.lineTo(w * (rx - 0.12), h * (ry + rh));
    ctx.closePath();
    ctx.fill();
  }
}

function paintCobaltMotif(ctx: CanvasRenderingContext2D, w: number, h: number) {
  ctx.fillStyle = "hsl(217 94% 46%)";
  ctx.fillRect(0, 0, w, h);

  ctx.strokeStyle = "hsl(200 94% 80%)";
  ctx.lineWidth = w * 0.085;
  ctx.lineCap = "round";
  for (let row = 0; row < 5; row++) {
    const y = h * (0.14 + row * 0.2);
    ctx.beginPath();
    ctx.moveTo(-w * 0.1, y + h * 0.06);
    ctx.quadraticCurveTo(w * 0.25, y - h * 0.07, w * 0.5, y + h * 0.04);
    ctx.quadraticCurveTo(w * 0.75, y + h * 0.15, w * 1.1, y - h * 0.02);
    ctx.stroke();
  }

  ctx.fillStyle = "hsl(220 92% 34%)";
  ctx.beginPath();
  ctx.arc(w * 0.18, h * 0.88, w * 0.28, 0, Math.PI * 2);
  ctx.arc(w * 0.84, h * 0.84, w * 0.24, 0, Math.PI * 2);
  ctx.fill();
}

const PAINTERS = [paintEmberMotif, paintGlacierMotif, paintOrchidMotif, paintCobaltMotif] as const;

export function buildColumnTextures(count: number): HTMLCanvasElement[] {
  const width = 480;
  const height = 640;
  const textures: HTMLCanvasElement[] = [];

  for (let i = 0; i < count; i++) {
    const offscreen = document.createElement("canvas");
    offscreen.width = width;
    offscreen.height = height;
    const ctx = offscreen.getContext("2d");
    if (ctx) {
      PAINTERS[i % PAINTERS.length](ctx, width, height);
    }
    textures.push(offscreen);
  }

  return textures;
}

export function drawCover(
  ctx: CanvasRenderingContext2D,
  source: HTMLCanvasElement,
  dx: number,
  dy: number,
  dw: number,
  dh: number,
) {
  const srcAspect = source.width / source.height;
  const destAspect = dw / dh;
  let sw: number;
  let sh: number;
  let sx: number;
  let sy: number;

  if (srcAspect > destAspect) {
    sh = source.height;
    sw = sh * destAspect;
    sx = (source.width - sw) / 2;
    sy = 0;
  } else {
    sw = source.width;
    sh = sw / destAspect;
    sx = 0;
    sy = (source.height - sh) / 2;
  }

  ctx.drawImage(source, sx, sy, sw, sh, dx, dy, dw, dh);
}

