  font-size: 15px;
  font-weight: 300;
  line-height: 1.7;
}

.container {
  box-sizing: border-box;
  width: 100%;
  margin-inline: auto;
  padding-inline: 16px;
}

@media (min-width: 1536px) {
  .container {
    max-width: 1400px;
  }
}

.head {
  margin-bottom: 48px;
}

.label {
  display: block;
  margin-bottom: 16px;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.35em;
  text-transform: uppercase;
  color: var(--rk-fg-muted);
}

.title {
  margin: 0;
  font-family: var(--rk-font-display);
  font-size: 48px;
  font-weight: 700;
  line-height: 0.82;
  letter-spacing: -0.06em;
  text-transform: uppercase;
}

.grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
}

.tile {
  position: relative;
  display: block;
  overflow: hidden;
  aspect-ratio: 3 / 4;
  color: inherit;
  text-decoration: none;
  transition: clip-path 0.45s var(--rk-ease);
}

.tile:focus-visible {
  outline: 2px solid var(--rk-fg);
  outline-offset: -4px;
}

.image {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 700ms cubic-bezier(0.4, 0, 0.2, 1);
}

.tile:hover .image {
  transform: scale(1.05);
}

.shade {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(
    to top,
    color-mix(in srgb, var(--rk-fg) 80%, transparent),
    color-mix(in srgb, var(--rk-fg) 30%, transparent),
    transparent
  );
}

.caption {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 10;
  padding: 16px;
}

.tileTitle {
