}
.input:focus-visible,
.checkbox:focus-visible,
.star:focus-visible,
.submitBtn:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--rk-fg) 90%, transparent);
  outline-offset: 2px;
}
.checkLabel {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  cursor: pointer;
  font-size: 13px;
